INSERT INTO `boxofficetb` (`movieno`, `movienm`, `directornm`, `releaseday`, `ratingno`, `times`, `intro`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `genre`, `actor`, `salesAcc`, `audiAcc`, `ranking`, `status`, `typeNm`, `showType`) VALUES ('b20167904','라라랜드','데이미언 셔젤','2016-12-07','12세이상관람가',127,'차들로 빽빽이 들어찬 LA의 고속도로. 거북이 걸음이던 도로가 뚫리기 시작하지만 미아 지금 손에 든 연기 오디션 대본을 놓지 못한다. 세바스찬은 경적을 누르며 미아를 노려보고는 사라진다. 악연의 시작. 이후 미아는 감미로운 피아노 선율에 이끌려 재즈바로 향하는데, 연주자가 바로 세바스찬이다. 미아가 세바스찬에게 인사를 건네려고 다가가던 순간은 하필 그가 재즈바의 레퍼토리를 무시하고 연주한 탓에 해고된 직후. 세바스찬은 인사를 건네려 다가온 미아를 쌩하니 스쳐 지나가버린다. 세 번째로 두 사람은 파티에 온 손님과 출장 밴드의 키보드 연주자로 다시 만나는데...','https://image.tmdb.org/t/p/w1280/nlPCdZlHtRNcF6C9hzUH4ebmV1w.jpg','https://image.tmdb.org/t/p/w1280/ad9ndytwOckyShSc0A6tx1rZRkW.jpg','https://www.youtube.com/embed/Zfy4rGzZDes','https://image.tmdb.org/t/p/w1280/nlPCdZlHtRNcF6C9hzUH4ebmV1w.jpg,https://image.tmdb.org/t/p/w1280/2wmDyHz4gvF6m51IQZJnJzlLsnz.jpg,https://image.tmdb.org/t/p/w1280/rVRtRE6HJ5xbdo5jd9aTT8tEVaF.jpg,https://image.tmdb.org/t/p/w1280/nyuzfjAbuSel6dVKY4zFo95ugUf.jpg,https://image.tmdb.org/t/p/w1280/z830hvnEW6E7KyMSLRKm4HvJRhN.jpg,https://image.tmdb.org/t/p/w1280/meGzYSwHzBWNQk9lYVNxdUrFqiC.jpg,https://image.tmdb.org/t/p/w1280/ik2D3KqxFD0O0Bc3Wv1CZm8sOg8.jpg,https://image.tmdb.org/t/p/w1280/tlCBtqrhbPcuXVXoxmQ0AYfUstt.jpg,https://image.tmdb.org/t/p/w1280/qJeU7KM4nT2C1WpOrwPcSDGFUWE.jpg,https://image.tmdb.org/t/p/w1280/hRBHmLny8ntncInmzCyREooTlIt.jpg,https://image.tmdb.org/t/p/w1280/pnFOEnr0T1oqdvfvLMRF03gS95l.jpg,https://image.tmdb.org/t/p/w1280/17QOQENrIS5DvazwpqW6jrcWA1T.jpg','드라마,뮤지컬,멜로/로맨스','엠마 스톤,라이언 고슬링,핀 위트록,J.K. 시몬스,로즈마리 드윗','32154525528',3865360,4,'개봉','장편','2D 디지털 수화, IMAX, DOLBYCINEMA, 2D 디지털 가치봄, 2D 디지털');
INSERT INTO `boxofficetb` (`movieno`, `movienm`, `directornm`, `releaseday`, `ratingno`, `times`, `intro`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `genre`, `actor`, `salesAcc`, `audiAcc`, `ranking`, `status`, `typeNm`, `showType`) VALUES ('b20210087','듄','드니 빌뇌브','2021-10-20','12세이상관람가',155,'10191년, 아트레이데스 가문의 후계자인 폴은 시간과 공간을 초월해 과거와 미래를 모두 볼 수 있고, 더 나은 미래를 만들 유일한 구원자인 예지된 자의 운명을 타고났다. 그리고 어떤 계시처럼 매일 꿈에서 아라키스의 행성에 있는 한 여인을 만난다. 귀족들이 지지하는 아트레이데스 가문에 대한 황제의 질투는 폴과 그 일족들을 죽음이 기다리는 아라키스로 이끄는데...','https://image.tmdb.org/t/p/w1280/qVgZu5BTx6pu4owCvVOm4zjTfOi.jpg','https://image.tmdb.org/t/p/w1280/7zV8FTYofAORGm0Umgh1mNNCym8.jpg','https://www.youtube.com/embed/oOKHVtgPJ00','https://image.tmdb.org/t/p/w1280/h61Kc0NC7d90jNwXfBx5js7DnSQ.jpg,https://image.tmdb.org/t/p/w1280/qVgZu5BTx6pu4owCvVOm4zjTfOi.jpg,https://image.tmdb.org/t/p/w1280/zRKQW58MBEY078AxkHxEJzUskCl.jpg,https://image.tmdb.org/t/p/w1280/jYEW5xZkZk2WTrdbMGAPFuBqbDc.jpg,https://image.tmdb.org/t/p/w1280/h3HsfV8Kn9Sz2QWUYYdP5ya23hx.jpg,https://image.tmdb.org/t/p/w1280/lzWHmYdfeFiMIY4JaMmtR7GEli3.jpg,https://image.tmdb.org/t/p/w1280/wYMbnrdRCREjNLwFlG5SLWzBjui.jpg,https://image.tmdb.org/t/p/w1280/jKhsC3yguywiKF1XA6OlslFhlwT.jpg,https://image.tmdb.org/t/p/w1280/guB0jTCIlMB5gJUILzZrxXVMuyJ.jpg,https://image.tmdb.org/t/p/w1280/1httqnYN5eMIkuxibCkRzInUvoS.jpg,https://image.tmdb.org/t/p/w1280/aHFgoGZ2VQNY45nJWGcBvszaMXz.jpg,https://image.tmdb.org/t/p/w1280/xS0g3s4blsiPmtpjjb7chFjI1ip.jpg','SF','티모시 샬라메,레베카 퍼거슨,오스카 아이삭,조슈 브롤린,제이슨 모모아,하비에르 바르뎀,젠데이아 콜먼,스텔란 스카스가드,장첸,데이브 바티스타,데이비드 다스트말치안,샬롯 램플링,샤론 던컨 브루스터,스티븐 헨더슨','19161501460',1694654,7,'개봉','장편','4D, IMAX, DOLBYCINEMA, 2D 디지털');
INSERT INTO `boxofficetb` (`movieno`, `movienm`, `directornm`, `releaseday`, `ratingno`, `times`, `intro`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `genre`, `actor`, `salesAcc`, `audiAcc`, `ranking`, `status`, `typeNm`, `showType`) VALUES ('b20259894','최종면접','김정훈','2026-11-04','15세이상관람가',107,'치열한 경쟁률을 뚫고 최종면접에 오른 6명의 지원자. 한 달간 팀 토론을 준비하며 전원 합격을 꿈꾸던 이들에게 제한시간 2시간 동안 단 1명의 합격자를 직접 뽑으라는 과제가 주어진다. 관찰 카메라의 압박 속에 합격자를 가려내기 위한 토론과 투표를 이어가던 중 그들은 각자의 이름이 적힌 의문의 봉투를 발견한다. 봉투가 열릴 때마다 진실을 알 수 없는 비밀들이 공개되고, 공정한 경쟁을 약속했던 최종면접은 걷잡을 수 없는 폭로전으로 치닫는데...','https://image.tmdb.org/t/p/w1280/zAaCSWZCs9IgEn7GiUkDuEtYQKf.jpg','https://image.tmdb.org/t/p/w1280/wImwvRmbR28hPNDmaj5W7zvxk0T.jpg','https://www.youtube.com/embed/mDqVXcgZKAM','https://image.tmdb.org/t/p/w1280/zAaCSWZCs9IgEn7GiUkDuEtYQKf.jpg,https://image.tmdb.org/t/p/w1280/9qBHkzVXkb9DLvIe5ULRf6Z6rD.jpg,https://image.tmdb.org/t/p/w1280/uhUOe5WCmh3e9BbbKGroIMrWz9R.jpg,https://image.tmdb.org/t/p/w1280/idUNghVaCtn3XpcpMPrPxkAdqOS.jpg,https://image.tmdb.org/t/p/w1280/x51c0SxvrNbAXlblUZZb3pAZJu4.jpg,https://image.tmdb.org/t/p/w1280/wf7gbuApFpXHvZ8r5rjNfWPUDbd.jpg,https://image.tmdb.org/t/p/w1280/8TC5GrCNyAj5adLQ57Bozknc8Wb.jpg,https://image.tmdb.org/t/p/w1280/xd4lZwYImOAYDAQP73jkYQcmVC2.jpg,https://image.tmdb.org/t/p/w1280/ubdo5IHJBBs947UJoDHS4vEBvTo.jpg,https://image.tmdb.org/t/p/w1280/64Kx0VpqYXwDpPaI8Mqdu2nXE3C.jpg','미스터리','조이현,김재원,신승호,강유석,곽동연,배강희','2928012270',290882,2,'개봉','장편','2D 디지털 한글자막 CC, 2D 디지털');
INSERT INTO `boxofficetb` (`movieno`, `movienm`, `directornm`, `releaseday`, `ratingno`, `times`, `intro`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `genre`, `actor`, `salesAcc`, `audiAcc`, `ranking`, `status`, `typeNm`, `showType`) VALUES ('b20261807','극장판 치이카와: 인어 섬의 비밀','오이카와 케이','2026-09-30','전체관람가',98,'어느 날, 광장에서 쉬고 있던 치이카와와 가르마 앞에 얼굴에 전단지를 붙인 토끼가 나타난다. 그곳엔 “특별한 섬으로의 초대”라는 글귀가 적혀 있는데... “섬에서 간단한 토벌만 해도 보수 100배!” “한정 섬라멘과 한정 디저트까지, 달콤한 것도 매콤한 것도 사실상 무료.” 솔깃한 문구에 이끌린 치이카와와 친구들은 섬에서 열리는 행사에 참가하기로 한다. 초대장의 내용이 어딘가 수상하다고 느끼는 해달과, 부푼 마음으로 배에 오르는 치이카와와 친구들. 모두가 기대를 안은 채 특별한 섬에 도착하는데! 과연 그 섬에는 어떤 비밀이 숨겨져 있을까...?!','https://image.tmdb.org/t/p/w1280/rVOll8XOde5BuIF4tGO1q0pfngQ.jpg','https://image.tmdb.org/t/p/w1280/5TMyytCI5Pfc9c1eNsljiCdiB05.jpg','https://www.youtube.com/embed/bqN9wLOsKdM','https://image.tmdb.org/t/p/w1280/rVOll8XOde5BuIF4tGO1q0pfngQ.jpg,https://image.tmdb.org/t/p/w1280/6efIfUaOqYKKWI5sSCilvqLIpeL.jpg,https://image.tmdb.org/t/p/w1280/h2CZMPoOyEM5DXBzpSKMck2Jj9V.jpg,https://image.tmdb.org/t/p/w1280/o8srzg3EIAruS6CO4FfU1EBHwt3.jpg,https://image.tmdb.org/t/p/w1280/sqHbEZ4MSWlcTg5p3JUv5b2p91S.jpg,https://image.tmdb.org/t/p/w1280/frtmVzNnOONgw8fBRnEJAKpVOXp.jpg,https://image.tmdb.org/t/p/w1280/nond4K6GxhRE9zKKdlEN5ADIEuc.jpg,https://image.tmdb.org/t/p/w1280/2A4hEbzhWgpmZMeDcgaVYzgH7pZ.jpg,https://image.tmdb.org/t/p/w1280/jXEPiXxLPgARyvNmhSLik7qOG0d.jpg,https://image.tmdb.org/t/p/w1280/5ezr3iT87KIMBMOJILAz4MMp291.jpg,https://image.tmdb.org/t/p/w1280/61ZFsrBzoViM8U1QTX1ADRocscN.jpg,https://image.tmdb.org/t/p/w1280/fwo9JtPnt0t3bPdcUIUvj5FncDS.jpg','애니메이션','아오키 하루카,타나카 마코토,오자와 아리,이주은,손정민,권다예','30340147110',2955237,3,'개봉','장편','4D, 2D 디지털 더빙, 4D 4D 더빙, 2D 디지털');
INSERT INTO `boxofficetb` (`movieno`, `movienm`, `directornm`, `releaseday`, `ratingno`, `times`, `intro`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `genre`, `actor`, `salesAcc`, `audiAcc`, `ranking`, `status`, `typeNm`, `showType`) VALUES ('b20264498','하트 오브 비스트','데이비드 에이어','2026-10-28','12세이상관람가',101,'특수부대에서 은퇴한 주임원사 제임스 벨몬트와 그의 군견 오딘. 전장에서 서로의 목숨을 지켜온 두 전우는 전쟁이 끝난 뒤에도 악몽과 트라우마에 시달린다. 둘은 수상비행기를 타고 알래스카의 외딴 호숫가를 찾아 잠시 고요한 시간을 보내지만, 돌아오는 하늘길에서 비행기가 추락하면서 문명과 단절된 광활한 황야 한가운데에 고립되고 만다. 가장 가까운 사람의 흔적까지는 무려 93킬로미터. 부상당한 몸을 이끌고 구조를 향해 걸음을 내딛은 제임스와 오딘 앞에는 거센 급류와 깎아지른 협곡, 굶주린 회색곰과 늑대 무리가 기다리고 있다. 인간의 잔혹함을 견뎌낸 개와 상처투성이가 된 사내, 이제 서로가 유일한 버팀목이 된 두 영혼은 과연 집으로 돌아갈 수 있을까?','https://image.tmdb.org/t/p/w1280/yE766yhgg98tKwTKd8CyNvAtmn6.jpg','https://image.tmdb.org/t/p/w1280/zC4E522V1n3H4SGdYOaiqhF5DnS.jpg','https://www.youtube.com/embed/bWx6nwUUpAw','https://image.tmdb.org/t/p/w1280/yE766yhgg98tKwTKd8CyNvAtmn6.jpg,https://image.tmdb.org/t/p/w1280/nlqHh1zGH8HYERr4eRICN9ligk.jpg,https://image.tmdb.org/t/p/w1280/6uVRPFflyJpo8Cx872olmlGTWla.jpg,https://image.tmdb.org/t/p/w1280/kpqsljPQtWqPKJBTAEtoXtQZ9Ko.jpg,https://image.tmdb.org/t/p/w1280/3rYXh9ldDCYTv5DweuJIXDgzJGd.jpg,https://image.tmdb.org/t/p/w1280/ybdbaIW4cO1kpnfQ11S9x19UDaH.jpg,https://image.tmdb.org/t/p/w1280/7jm4x9bKYs3UAHAlB0sOvMnH0Vp.jpg,https://image.tmdb.org/t/p/w1280/dLHAfnUMaNOfdqHVyxmwfP8hno.jpg,https://image.tmdb.org/t/p/w1280/hvouos17lFHsVE0Ty9wGqf0XE9u.jpg,https://image.tmdb.org/t/p/w1280/1JTncU2aUhhs70qhuPMHnLr3svL.jpg,https://image.tmdb.org/t/p/w1280/bicMU6xVD5deVyKP2azpyx7xkmH.jpg,https://image.tmdb.org/t/p/w1280/4RUBpqn88EvKvqNh2FH0dUCGuWZ.jpg','드라마,액션','브래드 피트,J.K. 시몬스','4468690230',456111,5,'개봉','장편','4D, 2D 디지털');
INSERT INTO `boxofficetb` (`movieno`, `movienm`, `directornm`, `releaseday`, `ratingno`, `times`, `intro`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `genre`, `actor`, `salesAcc`, `audiAcc`, `ranking`, `status`, `typeNm`, `showType`) VALUES ('b20264957','폴2: 데드포인트','마이클 스피어리그,피터 스피어이그','2026-11-11','15세이상관람가',98,'고도 제한 해제. 숨쉬기조차 힘든 해발 3,300m. 수십 년간 출입이 금지된 가장 위험한 산, \'콴\'. 한 번의 실수가 죽음으로 이어지는 곳. 이곳에선 비명마저 공중분해 된다.','https://image.tmdb.org/t/p/w1280/nGau0KBOaRILSK5MqFcuTfv7GMl.jpg','https://image.tmdb.org/t/p/w1280/v62qy8mNmseNhhsB2SXfpnbu741.jpg','https://www.youtube.com/embed/SVdAt0NjTTc','https://image.tmdb.org/t/p/w1280/nGau0KBOaRILSK5MqFcuTfv7GMl.jpg,https://image.tmdb.org/t/p/w1280/a5G1eG0Cqy7hoV22reB1vVqBfYA.jpg,https://image.tmdb.org/t/p/w1280/ehLnWR6RYRwCm8GF2ji8IU11vyH.jpg,https://image.tmdb.org/t/p/w1280/JzTmH0s7caaS20YyBQd3XFlHHp.jpg,https://image.tmdb.org/t/p/w1280/yBDxqDB29kpH9VojTytjGWBgmdJ.jpg,https://image.tmdb.org/t/p/w1280/yQXU4rgJ5LVCzn16SeIg34T35lV.jpg,https://image.tmdb.org/t/p/w1280/j5PqG9rD0aUUIKEkGkWt7AaKnRa.jpg,https://image.tmdb.org/t/p/w1280/bDQbd4qMy4bYXA4S36XZX5p68LU.jpg,https://image.tmdb.org/t/p/w1280/zwHsEcRcazZCxTWs9Glwo9qWZ0F.jpg,https://image.tmdb.org/t/p/w1280/7EV1WNgenluosQkFUXtbciWPN0A.jpg,https://image.tmdb.org/t/p/w1280/cPCgLDNCCUwtsedr181DtrlaDWx.jpg,https://image.tmdb.org/t/p/w1280/o8G95h5yJ5xVVZs1s3mCynmv9IK.jpg','스릴러,액션','버지니아 가드너,그레이스 캐롤라인 커리,해리엇 슬레이터,아르세마 토마스,톰 브리트니','1515453260',151644,1,'개봉','장편','4D, 2D 디지털');
INSERT INTO `boxofficetb` (`movieno`, `movienm`, `directornm`, `releaseday`, `ratingno`, `times`, `intro`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `genre`, `actor`, `salesAcc`, `audiAcc`, `ranking`, `status`, `typeNm`, `showType`) VALUES ('b20265420','스크루지: 크리스마스 캐럴','티 웨스트','2026-11-11','12세이상관람가',115,'거지도 구걸하지 않을 만큼 괴팍한 구두쇠 영감 스크루지. 모두가 즐거운 크리스마스조차 그에겐 시끌벅적하고 성가신 하루일 뿐이다. 그러던 크리스마스 이브, 그의 앞에 죽은 동업자의 유령이 나타나 지금처럼 살아간다면 끔찍한 운명을 맞이하게 될 것이라 경고하고, 이를 증명하기라도 하듯 곧이어 과거, 현재, 미래의 유령들이 차례로 스크루지를 찾아오며 그는 자신의 삶을 뒤바꿀 기묘한 모험을 하게 되는데…','https://image.tmdb.org/t/p/w1280/fdOVxyNNL95SuI8BGaN6vudEuYX.jpg','https://image.tmdb.org/t/p/w1280/mgWk3zPFLKisvKNtJGf6zxDX5gA.jpg','https://www.youtube.com/embed/DlTVejIWhUw','https://image.tmdb.org/t/p/w1280/fdOVxyNNL95SuI8BGaN6vudEuYX.jpg,https://image.tmdb.org/t/p/w1280/bF6nvHAt2jU7PnkOI4cnaUF2DZn.jpg,https://image.tmdb.org/t/p/w1280/oveb9ughaDh4GkjmVHvSgFnEzlM.jpg,https://image.tmdb.org/t/p/w1280/bG8uwYAq5Y9bPDaoxq2eHjopA9T.jpg,https://image.tmdb.org/t/p/w1280/4PDfd8uvrWAeRyvhUH9MACzXONz.jpg,https://image.tmdb.org/t/p/w1280/1xlpGn67p0rYP9tJq5W0H8NGXsL.jpg,https://image.tmdb.org/t/p/w1280/vrzZM9fdevl2syF6igHAMfRAwP8.jpg,https://image.tmdb.org/t/p/w1280/6VlTpWnm6DjNlK1NKFv1o4eMU33.jpg,https://image.tmdb.org/t/p/w1280/nAkH7yDch9ZsIPxuDTHOFZDI4hb.jpg,https://image.tmdb.org/t/p/w1280/dixTT6Dz5j2tsQZFrj4EFCiIgeL.jpg,https://image.tmdb.org/t/p/w1280/orfjYpvvHhEHMldmQn8lb8X6iw3.jpg,https://image.tmdb.org/t/p/w1280/ebZxZBDAw1SBpLSyqjKOs8TqzWX.jpg','드라마,판타지,스릴러','조니 뎁,이안 맥켈런,루퍼트 그린트,샘 클라플린,데이지 리들리','212479990',21360,9,'개봉','장편','2D 디지털');
INSERT INTO `boxofficetb` (`movieno`, `movienm`, `directornm`, `releaseday`, `ratingno`, `times`, `intro`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `genre`, `actor`, `salesAcc`, `audiAcc`, `ranking`, `status`, `typeNm`, `showType`) VALUES ('b20266765','와일드 호스 나인','마틴 맥도나','2026-11-04','15세이상관람가',116,'쿠데타를 앞둔 1973년 칠레, 오랜 세월 함께 일해 온 CIA 요원 크리스와 리는 지부장의 지시로 산티아고를 떠나 외딴 이스터섬으로 향한다. 정치적 격랑에서 멀어진 듯한 낙원에서도 두 사람은 자신들이 저질러 온 일들과 현재 진행 중인 음모에서 벗어나지 못한다. 크리스는 우연히 만난 반항적인 두 여학생에게 자신들의 정체를 농담처럼 털어놓고, 리는 그의 위태로운 언행을 수습하려 한다. 하지만 뜻밖의 만남은 가벼운 해프닝에 그치지 않고, 크리스와 학생들 사이에는 예상치 못한 유대가 싹튼다. 과거를 짊어진 요원들과 세상에 저항하는 학생들이 가까워질수록, 섬으로 떠난 여정은 점점 엉뚱한 방향으로 흘러간다. 이 낙원에서 가장 위험한 것은 음모일까, 서로에게 품기 시작한 마음일까?','https://image.tmdb.org/t/p/w1280/3uLA0ujne91bkzFStZICCYeqhnt.jpg','https://image.tmdb.org/t/p/w1280/iVWvR4BWhdirFIMQwS1yNp2Hcft.jpg','https://www.youtube.com/embed/RPpFc_oKcZc','','미스터리,범죄,스릴러','존 말코비치,샘 록웰,스티브 부세미,톰 웨이츠,파커 포시','435443590',41198,8,'개봉','장편','2D 디지털');
INSERT INTO `boxofficetb` (`movieno`, `movienm`, `directornm`, `releaseday`, `ratingno`, `times`, `intro`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `genre`, `actor`, `salesAcc`, `audiAcc`, `ranking`, `status`, `typeNm`, `showType`) VALUES ('b20267697','명탐정 코난: 30호 살인 사건','카마나카 노부하루','2026-11-05','12세이상관람가',93,'‘토토 타워’가 디자인된 1만 엔 신권 지폐가 발행되어 세상이 떠들썩한 가운데, 코난과 어린이 탐정단, 아가사 박사, 란과 소노코는 지폐 인쇄국 나가노 공장을 방문한다. 그 무렵, 경시청에서는 살인 사건 현장에서 발견된 신권 위조지폐로 인해 수사본부가 꾸려지고, 일본에서 발견된 30번째 위조지폐라는 점으로 인해 통칭 ‘30호 사건’으로 명명된다. 신권의 위조지폐 사건이 보도되면서 전국이 혼란해진 가운데 코난은 위조지폐가 인쇄된 것으로 추정되는 오사카의 지폐 인쇄국으로 향하고 거기서 헤이지가 수사에 합류한다. 그 외 시즈오카현과 가나가와현 등 각 지역에 위치한 지폐 인쇄국의 조사를 위해, 나가노현경의 야마토 칸스케, 모로후시 타카아키, 우에하라 유이 그리고 시즈오카현경의 요코미조 산고, 가나가와현경의 요코미조 쥬고 및 군마현경, 오사카부 경찰, 교토부 경찰까지 전국 경찰청에 이어 공안 후루야 레이, FBI 아카이 슈이치가 총출동해 국가적 위기에 맞선다! 통칭 30호, 신권 위조지폐 사건 발생! 전대미문 사건을 수사하기 위해 전원 출동! 국가적 위기에 맞서라!','https://image.tmdb.org/t/p/w1280/v0T74v8LPZBSL247oGeTOp06tnm.jpg','https://image.tmdb.org/t/p/w1280/8VIxElJnoGXJH4p3Av2BQwgcxpC.jpg','https://www.youtube.com/embed/7Ptzhr16J9g','https://image.tmdb.org/t/p/w1280/v0T74v8LPZBSL247oGeTOp06tnm.jpg,https://image.tmdb.org/t/p/w1280/269tZljYrnZ80G4GN6p3SWTwxzk.jpg,https://image.tmdb.org/t/p/w1280/gAJEaHNrA3bbh3kbzNTL7smmhEt.jpg,https://image.tmdb.org/t/p/w1280/zJRDpK1GmbCqrhxkPFl7cFn3VhY.jpg,https://image.tmdb.org/t/p/w1280/lWWJVOkaozZTYAoSrAshiQyHim2.jpg,https://image.tmdb.org/t/p/w1280/4pvxiCsznnJhSzEqNWkI8wVn1IS.jpg','애니메이션,액션,미스터리','타카야마 미나미,야마구치 캇페이','1784047150',176692,6,'개봉','장편','2D 디지털 더빙, 2D 디지털');
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1049439','골든 에이지','L\'Âge d\'Or','https://image.tmdb.org/t/p/w1280/gQQ7j5t5m2BYhk4gCOQzLccwtes.jpg','https://image.tmdb.org/t/p/w1280/sHy6hsrdvBH5wnLVjo6JyJhTgXQ.jpg','','https://image.tmdb.org/t/p/w1280/gQQ7j5t5m2BYhk4gCOQzLccwtes.jpg,https://image.tmdb.org/t/p/w1280/pbl15HnMVN50IwyQKUNL0RvLLL6.jpg,https://image.tmdb.org/t/p/w1280/gqeyu5njNNnFI78Vvu45kPgiFJg.jpg,https://image.tmdb.org/t/p/w1280/GHasEDP3HeEforqefHmqGw8Lvx.jpg,https://image.tmdb.org/t/p/w1280/2dR5AiRIN2bnjBLyGtblaEMLuDW.jpg,https://image.tmdb.org/t/p/w1280/dpUUNERlP7Mk6qt28SfjtH7SEci.jpg,https://image.tmdb.org/t/p/w1280/rhyZCwbhYfeDaE718rmNjqhl4T9.jpg','2026-11-11','16세기 말, 신교도와 구교도의 대립으로 대륙간의 전쟁이 한창인 시대. 영국은 신교도인 여왕 엘리자베스 1세가 통치하고 있다. 구교도가 주권을 잡은 스페인은 왕위 계승 서열 2위인 메리 스튜어트를 이용해 영국을 점령하고자 엘리자베스의 암살음모를 계획한다. 국가 간의 동맹을 목적으로 여왕의 구혼자들이 줄을 잇는 사이, 엘리자베스는 자유로운 탐험가 월터 라일리 경에게 빠져들지만 나라를 통치하는 ‘여왕’의 위치 때문에 애써 마음을 숨긴다. 라일리 경에 대한 마음은 점점 커져만 가고 여자로서의 삶과 여왕으로서의 권위에서 갈등하던 엘리자베스는 메리 스튜어트의 암살 음모를 발각하게 된다. 반역자로 사형에 처해진 메리 스튜어트의 죽음을 빌미로 스페인은 영국과의 거대 전쟁을 선포하는데… 한 여자로서의 인생에 사랑이라는 축복 대신 전쟁이라는 무거운 짐을 짊어진 그녀는 운명이 자신의 어깨 위에 얹어놓은 여왕의 자리를 인정하고 검을 손에 쥔다. 그리고 이제, 스페인 무적함대에 맞선 역사상 가장 위대한 전쟁을 시작한다.','15세이상관람가','Bérenger Thouin','수헤일라 야쿠브,Vassili Schneider,Pierre-Antoine Billon,Yile Yara Vianello,Laïs Mayyas,Kevin Lissajoux','역사,드라마',112,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1050981','\'나는, 휴먼\' - Being Heumann','Being Heumann','https://image.tmdb.org/t/p/w1280/25aB8RXP4mfQLFRSuEEhk0d0sTC.jpg','https://image.tmdb.org/t/p/w1280/sa3PceDmJR9Bl249ci7UZDmGixu.jpg','https://www.youtube.com/embed/CQp2pUXLvJk','https://image.tmdb.org/t/p/w1280/gquyc1tmWDHvwP6g0K7eazQbadJ.jpg,https://image.tmdb.org/t/p/w1280/ha9Wld7Rc6PsXrmxMf3Le4IwPg3.jpg,https://image.tmdb.org/t/p/w1280/j5lno3VxKr8wPaq9qHioMVHRJNP.jpg,https://image.tmdb.org/t/p/w1280/vUftraMp6rnTGqQ3Ba8ghRXSEx8.jpg,https://image.tmdb.org/t/p/w1280/v66Vj2sO3TeKaPqZWr6CDcyhL6V.jpg,https://image.tmdb.org/t/p/w1280/lSPmPkGZNkzh550a7Woirq4bDvx.jpg,https://image.tmdb.org/t/p/w1280/jIOnYY4I02hJaqD2qJ9rtmEfG0w.jpg,https://image.tmdb.org/t/p/w1280/c0o10GhlxMVGJMSChrBrtdk8xup.jpg,https://image.tmdb.org/t/p/w1280/9XERuLSFUWLJGH0N1S7nL3vPz4j.jpg,https://image.tmdb.org/t/p/w1280/qFDjQuuvwW9kSM0AdHUGGr7319Q.jpg,https://image.tmdb.org/t/p/w1280/ltrzoWNmgUxBcIbetUeclLakS5z.jpg,https://image.tmdb.org/t/p/w1280/opTJNDxGyrH3YxBL85cEietXKbR.jpg','2026-11-06','억척스럽고 반항적이며 더는 짐짝 취급당하지 않겠다는 주디 휴먼은 자신의 분노를 혁명으로 바꾼다. 1977년, 주디와 100여 명 규모의 장애인 인권 시위대는 아주 강력한 메시지를 보낸다. 망가진 것은 우리가 아니라 시스템이라고.','15세이상관람가','션 헤이더','Ruth Madeley,마크 러팔로,딜런 오브라이언,Madeline Delp,Roberta Colindrez,Jon Beavers,Antwan Tolliver,레이 피셔,Andrew Pilkington,Michael Patrick Thornton,Russell Harvard,대니얼 듀랜트,Charlie Rush-Reese,Rio Finnegan,D\'Arcee Charington Neal,Will Brill,롭 딜레이니,Matthew Jeffers,Siena Rafter,Rein Barcel,Stephen Adly Guirgis,데이비드 휴렛,Raphael Grosz-Harvey,Natalie Lisinska,Tattiawna Jones,Joe Cobden,Missy Yager,Ryan Allen,Prince Amponsah,Linden Porco,Amanda Richer,Alex Bulmer,Madison Tevlin,Julie Sawchuk,Nic Novicki,Yousef Kadoura,Jamie O\'Connell,Ty Kostyk,Lindsay Leese,L.A. Sweeney,Obi D\'Meano,Ghiselle Camacho,Jeff Geddis,Jo-Ann Martin,Lynnette Taylor,Leo Petrus,Mark MacRae,Burt Wolloston,Dylan Taylor,Morgan Kelly,Colin Platt,Colin Doyle,Bonnie Wong,Kyle Kirkpatrick,Sofía Rodríguez,Steve Curto,Milo Newsom,Aniko Newsom,Pamela Turnersmith,Oda Al-anizi,Pelumi Babalola,Deniece Balinda,Mitch Bruce,Stephanie Carpanini,Dominic Gomez,Jailen Gonzalez-Mattei,Vanessa Leu,Taylor Lindsay-Noel,Kateryna Lukiianova,Breanna Manley,Kristy Mikelait,Eric Morden,Mike Morden,Leilani Musa,Tai Young,Yuki Ng,Francesca Nocera,Skylar Petra,Oliver Sawchuk,Elijah Slater,Anna Wiley,Russell Winkelaar,Ricky Ye','드라마,역사',127,NULL,1,'2026-11-17 11:44:06',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1151422','카르멘','Royal Opera House: Carmen','https://image.tmdb.org/t/p/w1280/h7vL21Xqn7kpIO764aEVFscoqDl.jpg','https://image.tmdb.org/t/p/w1280/vyn1Zw38v5ePxIIhtHVZ8sgoUSz.jpg','','https://image.tmdb.org/t/p/w1280/h7vL21Xqn7kpIO764aEVFscoqDl.jpg','2026-11-10','세비야의 담배공장 앞, 미카엘라가 남자친구 호세를 만나러 온다. 담배공장에서 휴식을 알리는 종소리가 울리자 아가씨들이 쏟아져 나온다. 이들은 마침 심심해 하던 군인들과 서로 웃고 유혹하면서 시간을 보낸다. 여인들 중 단연 최고는 가무잡잡한 피부의 집시 카르멘이다. 카르멘은 호세를 유혹하지마 호세는 눈길조차 주지 않는다. 카르멘은 폭력 혐의로 체포되고 호세가 카르멘을 감방까지 연행한다. 호세는 카르멘의 매력에 빠져 그녀를 도망치게 도와준다. 마을의 어느 주막, 호세는 카르멘이 자기에게 관심이 있다고 생각해 그녀를 떠나지 못한다. 그러나 카르멘의 마음은 투우사 에스카미요에게로 향한다. 사랑에 눈이 먼 호세는 에스카미요와 칼싸움을 벌이고 이로인해 카르멘의 마음은 호세에게서 완전히 떠난다. 마침 호세의 여자 친구 미카엘라가 그를 찾아 산골짜기로 올라온다. 미카엘라는 호세에게 어머니가 돌아가시게 생겼으니 어서 고향으로 돌아가자고 애원한다. 호세는 카르멘에게 미련이 남지만 어머니를 생각해 마지못해 고향으로 돌아갈 결심한다. 투우장 밖, 에스카미요가 카르멘과 팔짱을 끼고 등장한다. 그 뒤를 호세가 한심하고 초라한 모습으로 따른다. 카르멘에게 “제발 나를 사랑해주시오!”라고 외치지만 카르멘의 대답은 차갑다. 카르멘에게 버림받은 호세는 순간 정신이 돌아버린다. 그는 칼을 꺼내 미친 듯이 카르멘을 찌른다. 사람들이 투우장 밖으로 쏟아져 나오다가 새하얀 햇빛 아래 장미꽃처럼 빨간 피를 흘리며 죽어 있는 카르멘을 목격한다.','15세이상관람가','Damiano Michieletto','Aigul Akhmetshina,Piotr Beczała,Kostas Smoriginas,Olga Kulchynska,Blaise Malaba','음악',196,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1241052','마우스','Mouse','https://image.tmdb.org/t/p/w1280/1pR6uu0e9h4tJiSuYLuiRm7id6x.jpg','https://image.tmdb.org/t/p/w1280/sdr2ofCHCqeBmDu7ekWXrzOTuRa.jpg','https://www.youtube.com/embed/Ngllukzkc_Y','https://image.tmdb.org/t/p/w1280/1pR6uu0e9h4tJiSuYLuiRm7id6x.jpg,https://image.tmdb.org/t/p/w1280/pWxGu2Is2J0kReGDbQazGvrxJI9.jpg','2026-11-06','고등학교 졸업 반을 앞둔 여름의 시작, 캘리와 미니의 관계는 갑작스러운 변화를 맞이한다. 카리스마 넘치는 단짝 친구를 잃고 방향을 상실한 미니는 캘리의 어머니와 복잡미묘한 우정을 쌓기 시작한다.','15세이상관람가','Kelly O\'Sullivan,Alex Thompson','소피 오코네도,캐서린 말렌 쿠퍼러,클로에 콜맨,데이비드 하이드 피어스,타라 말렌,이만 벨라니,Beck Nolan,Addisyn Grace Cain,오드리 그레이스 마샬,Christopher R Ellis,Mary Kathryn Bryant,Barry Clifton,Raeden Greer,Mary Hollis Inboden,Duane Jackson,Abigail Rose Solomon,Philip McDermott Young,Patchez Black,Kyleigh Box,Madelyn Hendrickson,Mark Alan Jaeger,Christen Burke Pitts,Grace Pitts,Novalie Ruth,Sarah Switzer','드라마,코미디',120,NULL,1,'2026-11-17 11:44:06',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1241478','지미','Jimmy','https://image.tmdb.org/t/p/w1280/2q3oieEIadF90wOtm9WGX5vrqUR.jpg','https://image.tmdb.org/t/p/w1280/xcMiTqj4kvSnUHhSLZ1WUvI9rzH.jpg','https://www.youtube.com/embed/Ru8LJGsRDgY','https://image.tmdb.org/t/p/w1280/2q3oieEIadF90wOtm9WGX5vrqUR.jpg,https://image.tmdb.org/t/p/w1280/bxNaI55NAz3xiEHOAXtQul3wSid.jpg,https://image.tmdb.org/t/p/w1280/v2sDJbVRiIcKqdUiqcgXN9QZvOG.jpg,https://image.tmdb.org/t/p/w1280/fYEHvD5H3P5BDy5W5tpHfsySaM9.jpg,https://image.tmdb.org/t/p/w1280/aiB2TPgCOXs8waILDQcyvY9tOn4.jpg,https://image.tmdb.org/t/p/w1280/liuw4mkbFDMB4r3fi7dp9xyRj5F.jpg,https://image.tmdb.org/t/p/w1280/7WlAdSAhMF23xPd4rqSBCpRMwyY.jpg,https://image.tmdb.org/t/p/w1280/kUoYhIhHZInR6Jlb6Dn9v1s8lvn.jpg,https://image.tmdb.org/t/p/w1280/oXcSw1VxzZ6zqLxzBIuY75qOeJl.jpg,https://image.tmdb.org/t/p/w1280/1c7jSLuw47FXmi7akVAmjurHGdQ.jpg,https://image.tmdb.org/t/p/w1280/4syptxLe5WZUhmxeQS2exF9NwpY.jpg,https://image.tmdb.org/t/p/w1280/sqvSkuqGloOxg4QQGn3rOVgISJY.jpg','2026-11-06','오스카 수상 배우 지미 스튜어트가 제2차 세계대전 폭격기 조종사로 20 회의 전투 임무를 수행한 뒤, <멋진인생>의 조지 베일리를 통해 다시 삶과 연기의 의미를 찾아가는 실화 기반 전기 드라마.','12세이상관람가','Aaron Burns','K.J. 아파,제이슨 알렉산더,Max Casella,Sarah Drew,Julian Works,Jen Lilley,크리스토퍼 맥도널드,Kara Killmer,닐 맥도너,롭 리글,Jemma Donovan,Aidan Thornton,Seán Condon,Ian Dillon,Conor Thornton,Louis Furney,Karolyn Grimes,Liam Bixby,Marc Malkin,Jean Law,Daniel Fee,라슨 톰슨,Michael James Ford,Aidan Redmond,Brendan Dempsey,Tadgh Snodgrass,Edgar Abram,Oskar Smith,Adam Phelan,Emmanuel Okoye,Andrew Kingston,Elysée Sanvillé,Courtney D\'Angelo,Michael De Brún,Zara Bridget Dillon,Conor Griffin,Billy Hallowell,Craig Hogan,Rylee Hosford,Moses Murphy,Danny Power,Austin Prebula,Paul Rowan,Rebecca Ryan,Sam Lucas Smith,Nathan Snow,Kelly Stewart,Chloe Sullivan,Sarah Faye Terry,Chris A. Wilks,Karl Geiran,Littia Hatcher,Evelin Stern,Oisín O’Reilly','드라마,역사',120,NULL,1,'2026-11-17 11:44:06',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1244809','폭설','폭설','https://image.tmdb.org/t/p/w1280/3UXmXTfkekS0Dchl8iIqK7XJt0t.jpg','https://image.tmdb.org/t/p/w1280/xiBYIFWBrLD7Z7jWrt0e7YLLmfC.jpg','','https://image.tmdb.org/t/p/w1280/3UXmXTfkekS0Dchl8iIqK7XJt0t.jpg,https://image.tmdb.org/t/p/w1280/d98FbAeTN5DNbRhujT3tEkKI4ZC.jpg,https://image.tmdb.org/t/p/w1280/AiZlT4ZVH8H9OlQf5ATx9Op4A7P.jpg,https://image.tmdb.org/t/p/w1280/rjWhkMCfub7ynayFqc9NlKQJXqF.jpg,https://image.tmdb.org/t/p/w1280/u6rgAn2jKnoYWm149QNfpAyZ1Cg.jpg,https://image.tmdb.org/t/p/w1280/tPt3x9f0TMuWzh0aKttuwTwmwZy.jpg,https://image.tmdb.org/t/p/w1280/vWzsCKZ3OVguZtGHCiU5BzOE3El.jpg','2026-11-18','퇴직을 하루 앞둔 역장 갑수는 마지막 열차를 통과시키고 평생을 지켜오던 설오역을 떠날 준비를 한다. 하지만 하필 폭설이 쏟아지며 후임의 도착이 늦어지고, 설오역은 눈 속에 고립되고 만다. 다음 날, 후임이라는 놈이 설오역에 도착하지만 어딘가 수상하다. 그렇게 찝찝한 기분으로 인수인계를 이어가던 두 사람 앞에 의문의 시신이 나타나는데...','15세이상관람가','홍의정,박선우','김윤석,구교환,노윤서,박수영','스릴러,미스터리,드라마',89,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1255582','네가 그리울 거야','Eu Vou Ter Saudades de Você','https://image.tmdb.org/t/p/w1280/vlrfwLFmhYp1trKxIkezE28YC1z.jpg','https://image.tmdb.org/t/p/w1280/6NOJb3TEDvZQWIs7pWO1QlUBDjS.jpg','','https://image.tmdb.org/t/p/w1280/vlrfwLFmhYp1trKxIkezE28YC1z.jpg','2026-11-19','7년간의 연애 끝에 아만다와 카이오는 함께 살기 시작하지만, 사랑만으로는 충분하지 않다. 카이오는 아만다와의 미래를 꿈꾸고, 아만다는 그 이상의 무언가를 원한다. 그러던 중 아만다가 주앙을 만나면서 두 사람의 관계는 시험대에 오른다.','15세이상관람가','Daniel Ribeiro','Alice Marcone,Gabriel Lodi,Maite Schneider,Luca Scarpelli,Leona Jhovs,Rodolpho Correa,Clodd Dias,Olivia Lopes,Daniel Veiga,Jhonnã Bao,Anne Celestino','드라마,로맨스',87,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1299501','어웨이크닝','The Awakening','https://image.tmdb.org/t/p/w1280/8zjY32qSA82W1gLZ42gygWz1vTd.jpg','https://image.tmdb.org/t/p/w1280/eoxL6ixns1ofw6gq9AsFd1rduW3.jpg','https://www.youtube.com/embed/reDpHPVpIIU','https://image.tmdb.org/t/p/w1280/8zjY32qSA82W1gLZ42gygWz1vTd.jpg,https://image.tmdb.org/t/p/w1280/oC1yY4gvDctN0SEwgRMAjkiadA5.jpg','2026-11-10','레이는 820년의 긴 잠에서 깨어나 충실한 하인인 프랑켄슈타인에 의해 설립된 고등학교의 학생으로 새로운 삶을 시작한다. 그러나 다른 인간 학생들과의 평화로운 시절은 곧 \"유니언\"이라고 알려진 불가사의한 공격자들에 의해 중단된다.','15세이상관람가','Matt Routledge','Justin Tinto,앨리스 이브,피터 스토메어,Steven Berkoff,줄리안 글로버,Eddie Hall,케빈 스페이시,Matt Hookings,Carolyn Pickles,리언 허버트,Michael McKell,데이비드 바크-존스,Daniel O\'Reilly,Lewis Raymond Taylor','스릴러',90,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1300968','헝거게임 50번째 추첨의 날','The Hunger Games: Sunrise on the Reaping','https://image.tmdb.org/t/p/w1280/aqFZcr2dxSZ2UwWSo1WC6C0rwDf.jpg','https://image.tmdb.org/t/p/w1280/6ehDHRVDtwe1oMu6EMtKC3SoVER.jpg','https://www.youtube.com/embed/0OHZYI242VA','https://image.tmdb.org/t/p/w1280/aqFZcr2dxSZ2UwWSo1WC6C0rwDf.jpg,https://image.tmdb.org/t/p/w1280/cCGTwo2qtzKcvXvFvkvXO4J2f2D.jpg,https://image.tmdb.org/t/p/w1280/6bM4RwgUsL8hPz5FjFDKM0vrDu2.jpg,https://image.tmdb.org/t/p/w1280/qW47xOGl0dOMRUtAS2XugBlOO1t.jpg,https://image.tmdb.org/t/p/w1280/11Xur5nj09Lsz5sVCGThbPAUTac.jpg,https://image.tmdb.org/t/p/w1280/9B3AMSs7A3bqqFLKlOv6W4LyAHG.jpg,https://image.tmdb.org/t/p/w1280/497KYpXqaxh99RPMVmsxAg76Nal.jpg,https://image.tmdb.org/t/p/w1280/vezToHmUsQApQKHChwz8E9LBfEA.jpg,https://image.tmdb.org/t/p/w1280/8F2zI3KRfPZY4tMYWG16VBLZRJK.jpg,https://image.tmdb.org/t/p/w1280/rdLax1R7YPEVi9z3fTofzthAOAD.jpg,https://image.tmdb.org/t/p/w1280/oEDuHEef57DDoyZG4QTrzrofpr8.jpg,https://image.tmdb.org/t/p/w1280/oRsu3HqtGOQlPZIIT0XLYGf0Z60.jpg','2026-11-18','캐피톨을 비웃어 ‘역대 최하점’을 받은 흙수저 소년 헤이미치. 모두가 소년이 가장 먼저 죽을 것이라며 돈을 걸 때, 1점짜리 천재의 머릿속엔 이미 데스게임의 룰을 부술 완벽한 설계가 끝나 있었다. 생존율 0%, 맹독의 숲에 던져진 48명의 희생양, 오직 완력만 믿고 돌진하는 엘리트들 사이에서 헤이미치의 진짜 사냥감은 다른 참가자가 아닌 ‘시스템’ 그 자체다. 무기는 필요 없다. 오직 지능으로 판을 지배하는 1점짜리 천재의 뇌지컬 생존기가 폭발한다.','12세이상관람가','프랜시스 로렌스','조셉 자다,맥케나 그레이스,랄프 파인즈,제시 플레먼스,글렌 클로즈,휘트니 피크,엘 패닝,키어런 컬킨,마야 호크,켈빈 해리슨 주니어,릴리 테일러,벤 왕,Molly McCann,Iona Bell,빌리 포터,Jhaleil Swaby,Laura Marcus,Percy Daggs IV,Rada Rae,Sky Frances,Tatyana Muzondo,Alina Reid,Salimou Thiam,Scot Greenan,Grace Ackary,John Doeble,Kaine Buffonge,Kara Tointon,Smylie Bradwell,Jeff Hallman,Serafin Mishiev,Melody Brown,Jefferson White,아이리스 아패토우,에드빈 리딩,Sandra Förster,Jax Guerrero,Devon Singletary,제니퍼 로렌스,조쉬 허처슨,우디 해럴슨,Benjamin Lucca,Julius Gause,Pola Geiger,Halima Ilter,Nikita Takasaki,Jamal Ashu Salamone,Rowen Bloom Sargent,Julius Trabolt,Paloma Padrock,Michael Schweisser,Elisabeth Heinz,Sophie Paasch,Zahel Anwary,Anastasia Detkov,Dias Kaldybekov,Emil Bloch,Jelle Flora Pouwels,Padmé Hamdemir,Christian Camillo Engel,Seedy Touray,Deyar Alkalash,Tristan Frederichs,Elizabeth Louise Churcher,Madeleine Wagenitz,Ilja Bultmann,Thien Phuoc Nguyen,Anna-Lena Treue,Victor Bass,Carmen Sampoko Guissou,Vincent Schwalm,Marie Luise Forberg,Luis Santiago Klier,Madouna Said,Jack Lee Thomas,Lisa Lekutat,Suryani Hardt,Berline Glebke,Shahriar Sadeghian,Cameron MacConomy,Philipp Karner,Dani Klupsch,Pauline Nitschke,Ariel Prubner,Leon Vervoort,Samia Hofmann,Daniel Traub,Max Urlacher,Alma Weidenbach,Sydney LaFaire','SF,액션,모험',159,NULL,1,'2026-11-17 11:44:06',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1312310','시골 소년 가벵과 함께한 10년','Gabin','https://image.tmdb.org/t/p/w1280/ofuOuq4xd8oF5Q3v5Kg69jfoFhj.jpg','https://image.tmdb.org/t/p/w1280/cVEnzhnfFvfwAeqF7hHAj6hPG7t.jpg','https://www.youtube.com/embed/_4XmhCbavrs','https://image.tmdb.org/t/p/w1280/ofuOuq4xd8oF5Q3v5Kg69jfoFhj.jpg,https://image.tmdb.org/t/p/w1280/94SHHcqlkGd5h7OUpHMb1fHSjcN.jpg,https://image.tmdb.org/t/p/w1280/b2PkxzD1ApaEKATxzA9NZyDCtbm.jpg','2026-11-13','가족에 대한 애정과 자유에 대한 열망, 현실에 대한 책임과 미래에 대한 불안 사이에서 갈등하는 가벵은 프랑스 북부 시골 노동자 계급 출신의 소년이다. 가벵의 아버지는 아들이 정육점을 물려받길 원하고, 농장에서 매일 고된 노동을 하는 어머니를 돕기에 가벵은 아직 어리다. 8살부터 18살까지, 소년의 시간을 10년간 담아낸 막상스 부아제 감독의 다큐멘터리는 시간의 물성을 스크린 위에 경이롭게 새겨 넣는다.','15세이상관람가','Maxence Voiseux','Gabin Jourdel,Patricia Jourdel,Dominique Jourdel,Lilou Duflos-Lamotte,Catherine Ranson','다큐멘터리',105,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1313587','그로테스크','GROTESQQQUE -グロテスク-','https://image.tmdb.org/t/p/w1280/mKUCCoBntwXt0WpSxoAhgFpV71b.jpg','https://image.tmdb.org/t/p/w1280/32IXjbgWex06JDdXZSPQA0Hu2Q3.jpg','https://www.youtube.com/embed/oqZaJgF4sfE','https://image.tmdb.org/t/p/w1280/j0F505sKGGnb1f1p5HXYMLfBzOX.jpg,https://image.tmdb.org/t/p/w1280/mKUCCoBntwXt0WpSxoAhgFpV71b.jpg,https://image.tmdb.org/t/p/w1280/mQCcSq1l5xq2eSNVXIm9BsM8mGR.jpg,https://image.tmdb.org/t/p/w1280/U7fU0Q0drwnBPzQwFHnQ8E0X0B.jpg,https://image.tmdb.org/t/p/w1280/sz5ZYDZET19arQ9PmbGZvhbdyu5.jpg,https://image.tmdb.org/t/p/w1280/7s2zxlQorX238ch9Yz6M3HfHl5f.jpg,https://image.tmdb.org/t/p/w1280/yDnrUXGCwWEBKk6TbMTxnJ6djw.jpg,https://image.tmdb.org/t/p/w1280/jtPKrKbKHeBd2bBrfezAHjd0F0H.jpg,https://image.tmdb.org/t/p/w1280/x4u6L3RHgyh3PmSPZD2nrvIBK5E.jpg','2026-11-06','지구의 문화와 사랑에 빠진 우주인 소녀 ‘엘리’는 우주국 공무원 ‘쿠니무라 켄토’와 함께 ‘친구 찾기’ 프로젝트에 돌입하지만, 자꾸 폭주하는 능력 때문에 침략자라는 의심을 받게 된다. (ÆLIENS(에일리언즈)) 아침이 오지 않는 도시 ‘갸루즈 도쿄’에서는 매일 밤 게임의 ‘퀸’이 되기 위한 소녀들의 배틀이 벌어진다. 한편, 등교 거부 소녀 ‘스텔라’는 게임의 숨겨진 비밀을 알게 된다. (4649★소녀) 인류가 멸망한 세계, 순혈 뱀파이어 ‘아야메’와 그녀의 흡혈을 통해 살아남은 세 소녀는 여행을 이어간다. 그러던 중 영원을 살아가는 ‘아야메’의 몸에 이상이 생긴다. (녹턴 ~이 그로테스크한 밤에~) 외계인, 갸루, 뱀파이어. 뒤틀리고 제각각이지만 한없이 아름다운, 소녀들의 GROTESQQQUE한 이야기가 펼쳐진다!','15세이상관람가','니시고리 아츠시,Takahiro Miura','이치노세 카나,호시노 겐,미나미 사라,하세가와 이쿠미,하야미 사오리,우치다 마아야,안자이 치카,토미타 미유,오오쿠보 루미,쿠기미야 리에,井上和,나카니시 아루노,一ノ瀬美空,冨里奈央,오오츠카 아키오,히카사 요코,스기야마 리호,오오하시 아야카','애니메이션,SF,액션,드라마',104,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1314786','세타 요원','Zeta','https://image.tmdb.org/t/p/w1280/cmP55W8EqqIE41Ck9D7uWRpzLwS.jpg','https://image.tmdb.org/t/p/w1280/7x7yFQKrz5kZN0LOUe5ZuwbZSdm.jpg','https://www.youtube.com/embed/d56tjzLzYZM','https://image.tmdb.org/t/p/w1280/cmP55W8EqqIE41Ck9D7uWRpzLwS.jpg,https://image.tmdb.org/t/p/w1280/ptcyGmBonW6mDQmrPhXbt6Rjrlp.jpg,https://image.tmdb.org/t/p/w1280/jtO2Mm5X22QmJZH8YyUMmG0ZXOV.jpg,https://image.tmdb.org/t/p/w1280/nsuqPeZcXiGTu7ezxuJpy7M6NEk.jpg,https://image.tmdb.org/t/p/w1280/ykkRklFvP0ev0EjHjpN2jXK5vPI.jpg,https://image.tmdb.org/t/p/w1280/hs8JJKFLU8uyQtPC2T0y3KfEtvP.jpg,https://image.tmdb.org/t/p/w1280/8qBVLReJWkhqArYlWiphru6Zcgf.jpg,https://image.tmdb.org/t/p/w1280/66Dli1GhY0HJe8sbTRuCl0hplPg.jpg,https://image.tmdb.org/t/p/w1280/uv4bvjZiR57wCRG89maKAZUdwBc.jpg,https://image.tmdb.org/t/p/w1280/7L1LODjoUAhA4IOwhr3HClitY8S.jpg,https://image.tmdb.org/t/p/w1280/7s1tQjErsV32qsnrgX3WTU9Gd5D.jpg,https://image.tmdb.org/t/p/w1280/muPyr43nVsBWvQUenhx9B2YNxwn.jpg','2026-11-13','전 세계 각지에서 전직 스페인 정보요원 4명이 동시에 암살된다. 이들이 수십 년 전 콜롬비아에서 수행된 비밀 작전 \'시에나가\'의 참여자들이었다는 사실을 알아낸 CNI는 CNI 최고의 요원 세타에게 유일한 생존자를 찾아 보호하라는 생애 가장 위험한 임무를 맡긴다. 여기에 \'시에나가\'의 비밀을 세타보다 더 잘 알고 있는 듯한 콜롬비아 최고의 요원 알파가 합류하며 사건은 예상치 못한 방향으로 흘러간다.','15세이상관람가','Dani de la Torre','마리오 카사스,Mariela Garriga,Luis Zahera,Nora Navas,Christian Tappan,Cristina Umaña,Ricardo de Barreiro,Luisa Vides Galiano,David Villamil,Amanda Goldsmith,Juan Sánchez McDonell,Ander Jiménez,Nieve de Medina,Federico Pérez Rey,Juan Manuel Orostegui,Pablo Álvarez,Ainhoa Larretxi,Luis Zanfir,Roberto Mateos,Fabián Aguilar,Ana Verónica Schultz,Vicente Genovés,Celia Maestre,Aníbal Soto,Elisabeth Bonjour,Sheyla Fariña,Alejandro Vergara,Sarah Cafaro,Miguel Brocca,Anai González Prieto,Javier Ortiz,Nolan Schultz,Mei Rodríguez,Pilar Gómez,Marvin Wycoff,Alejandro Martínez,Fernando Mariano,Filipe Afrika,Antonio Jiménez,Luis Carlos Ballestas,Alejandro Marzal,Ponce,Jorge Valder,Miguel Ángel Romero y León,Christian Rivas,Jhonathan Sáenz,Luis Jaspe,Dani Trujillo,Noa Badía,Fredrik Scheike,Jason Tigreros,Sandy García Unzón,Juan Aguilar,Gonzalo Duarte,Ziyi Yang,Hamilton Mosquera Gonzalías,Alejandra Restrepo Santacoloma,Luis Ávila','드라마,스릴러',133,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1381273','페이퍼 타이거','Paper Tiger','https://image.tmdb.org/t/p/w1280/6S41dEoKH2cxw20QgLxhnsQoLQF.jpg','https://image.tmdb.org/t/p/w1280/p6oLmq5KmuWY6uRXBQBL2q30jia.jpg','https://www.youtube.com/embed/UZC4qOE8t-E','https://image.tmdb.org/t/p/w1280/6S41dEoKH2cxw20QgLxhnsQoLQF.jpg,https://image.tmdb.org/t/p/w1280/1VhgzeA0tBbd7GtAw1d2nL3UUBk.jpg,https://image.tmdb.org/t/p/w1280/wg4Qr8ppCXDgCEgupW9lNsUijF7.jpg,https://image.tmdb.org/t/p/w1280/wwESZZLGEBxjYHYTuFsqX2jPgOh.jpg,https://image.tmdb.org/t/p/w1280/7MdKguHQw1n5Mfhj0vC5QRkrgj9.jpg,https://image.tmdb.org/t/p/w1280/AkOEM05vSzIUqx3cRP0OyGJ1PZH.jpg,https://image.tmdb.org/t/p/w1280/wjseI0S3RA0VzteewcfT1FX4h94.jpg,https://image.tmdb.org/t/p/w1280/wawjOe2dS0nX4Y0B0BmAMST77E1.jpg,https://image.tmdb.org/t/p/w1280/AaI4fea3SO7yk9iY8Yoj0eluV5I.jpg,https://image.tmdb.org/t/p/w1280/ibHspQFKwizoZbQmLdyQv7qZufH.jpg,https://image.tmdb.org/t/p/w1280/hBNkVZzbwK28wrAPk9uadyL8eRf.jpg,https://image.tmdb.org/t/p/w1280/lriRe2SIQgswWqc9tNJx8qSZHIU.jpg','2026-11-13','1980년대 뉴욕, 전기 엔지니어인 어윈은 전직 경찰인 형 게리의 제안에 따라 하천 정화사업을 벌이려다 러시아 마피아에게 연루된다.','15세이상관람가','제임스 그레이','마일스 텔러,애덤 드라이버,스칼렛 요한슨,Gavin Goudey,Roman Engel,Cindy Katz,Yavor Vesselinov,Victor Ptak,Dimiter D. Marinov,Raphael Corkhill,Roman Blat,Patrick Murney,Joel Marsh Garland,Michael Alix,Meredith Holzman,Rosslyn Luke,Grisha Reydler,Елена Соловей,Vadim Kroll,Debbie Troche,Wayne Chang','범죄,드라마,스릴러',114,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1383091','평범하기 위하여','有用的人','https://image.tmdb.org/t/p/w1280/eb9hvklJfQqkhHEQsWhwSZdkypa.jpg','https://image.tmdb.org/t/p/w1280/f2AHd0mWJrLLwc6elLcSNVbsy8f.jpg','https://www.youtube.com/embed/W6zIQjHx-1c','https://image.tmdb.org/t/p/w1280/eb9hvklJfQqkhHEQsWhwSZdkypa.jpg,https://image.tmdb.org/t/p/w1280/x4pIPaWGsFmkvQCWZ4UwQfZdENO.jpg,https://image.tmdb.org/t/p/w1280/lG2OmD4EWffnOjF3HWIrWRhCWVj.jpg,https://image.tmdb.org/t/p/w1280/pInYOm6LGyAuvL9Sly5j9BXFqiY.jpg','2026-11-13','한밤중에 아르바이트를 마친 뒤, 오토바이를 타고 귀가하던 위지에는 교통사고를 당한다. 대학생이자 웹디자이너인 위지에에게는 3년째 실직 중인 아버지와, 그런 아버지와는 거의 말을 섞지 않고 자식들에게만 집중하는 어머니, 이제 막 사춘기를 시작하는 여동생이 있다. 사고 가해자인 은퇴한 노인은 자신의 집을 위지에에게 양도하고, 치료비와 생활비를 매달 지급하며 보상의 책임을 다하고자 하지만 여전히 죄책감에 시달린다. 한편, 재정적으로, 감정적으로 위태로웠던 위지에의 가족들은 다시 따뜻한 저녁을 나눠 먹는 ‘식구’가 되어가고, 위지에는 또래의 재활치료사 이한을 만나 마음을 나누기 시작한다. 그러나 잠시의 ‘평범한’ 행복은 오래 가지 않는다.','12세이상관람가','리윈찬','楊一展,張詩盈,謝展榮,陳品嫙,梁修身,朱勻甄,朱芷瑩,連俞涵,梁正群,黃冠智,Phoenix Chang,施名帥,陳妤,李雪','드라마',112,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1426957','그 도시에서 가장 외로운 남자','The Loneliest Man in Town','https://image.tmdb.org/t/p/w1280/zeDYPzldn22WfFsnTfuBkCCFJIZ.jpg','https://image.tmdb.org/t/p/w1280/dm8HprLOd4uKCuik8gpXhpc8LwB.jpg','https://www.youtube.com/embed/-M4x9qXC71k','https://image.tmdb.org/t/p/w1280/zeDYPzldn22WfFsnTfuBkCCFJIZ.jpg,https://image.tmdb.org/t/p/w1280/t3ZwVqb0BFxZneoO6rXnav0QyZM.jpg','2026-11-13','알 쿡은 추억에 잠겨 살아간다. 아파트와 지하 작업실에 빼곡히 채워진 책, 비디오테이프, LP 음반은 그가 충실하게 살았던 한때의 흔적이자 그에게 남은 전부이다. 무자비한 부동산 개발회사가 그 집을 철거 대상으로 삼자 그의 안식처는 무너지게 된다. 이제 그는 폐허가 된 자신의 존재를 마주해야 한다.​','12세이상관람가','Tizza Covi,Rainer Frimmel','Alois Koch,Brigitte Meduna,Alfred Blechinger,Flurina Schneider,Sarah Morrissette,Natascha Hiermann,Ingrid Schaffernack','음악,드라마',86,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1453303','호루몽','호루몽','https://image.tmdb.org/t/p/w1280/lEo8FYHX3ENDmo9vEkyRRuG297k.jpg','https://image.tmdb.org/t/p/w1280/vH6TqikyX2FwjgToCwtearQ3ziB.jpg','','https://image.tmdb.org/t/p/w1280/lEo8FYHX3ENDmo9vEkyRRuG297k.jpg,https://image.tmdb.org/t/p/w1280/blzrKwHLSDl4Clbo5Tqam7sZn3L.jpg','2026-11-11','2017년, 일본의 지상파 방송이 쏘아 올린 가짜 뉴스 한 발. 재일 코리안 3세 신숙옥은 순식간에 나라의 적이 됐다. 제지공장으로 팔려 온 할머니, 어디에도 뿌리내리지 못한 채 떠돌았던 어머니. 그리고 버려진 내장 ‘호루몽’을 씹어 삼키며 살아낸 사람들. 100년의 시간이 켜켜이 쌓여, 마침내 한 사람의 목소리로 터진다. 얌전히 당해주지 않은 반격이 시작된다. 550만 엔 배상 판결. 방송은 결국 폐지됐다. 끝까지 물러서지 않은 한 사람이 마침내 세상을 뒤흔든 순간. 그러나 신숙옥의 싸움은 아직 끝나지 않았다.','15세이상관람가','이일하','Shin Sug-ok,Keiko Shiratori','다큐멘터리',101,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1480276','인헤릿','คุณยายวรนาฏ','https://image.tmdb.org/t/p/w1280/hLVFiEzMDsYk6CW5kpPE1T7f4WL.jpg','https://image.tmdb.org/t/p/w1280/cM32qqkGKN9iHT0YK7zxe7ZR85Z.jpg','https://www.youtube.com/embed/Iho_Pe9VqkM','https://image.tmdb.org/t/p/w1280/hLVFiEzMDsYk6CW5kpPE1T7f4WL.jpg,https://image.tmdb.org/t/p/w1280/9xX1vlldg2CoUWUuyHrk3mYPeHD.jpg,https://image.tmdb.org/t/p/w1280/s0DXF26hOFyP4TXHih9EzHnIECg.jpg','2026-11-19','수십 년간 소식이 끊겼던 워라낫 할머니가 가족들 앞에 나타난다. 카리스마 넘치는 아름다운 모습을 그대로 간직한 그녀의 등장에 집안은 재회의 반가움보다 불길한 긴장감으로 휩싸인다. 가문의 오래되고 무시무시한 비밀이 하나둘씩 드러나는 가운데, 유일하게 워라낫을 따르는 순수한 손녀 우이가 18세 생일을 맞는다.','15세이상관람가','บรรจง ปิสัญธนะกูล','다위까 호네,ธิติยา จิระพรศิลป์,สินจัย เปล่งพานิช,วรัทยา นิลคูหา,ตฤณ เศรษฐโชค,พงศธร จงวิลาส,ภาคิน คุณาอนุวิทย์,ชญานนท์ ภาคฐิน,ณัฐวดี พิภพพรชัย,กาญจนาพร ปลอดภัย,จุฑาพิชญ์ อินทร์จันทร์,โกวิท วัฒนกุล,ลลิต์ภัทร ศิริรัตน์','공포,스릴러,미스터리',128,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1498742','그들은 이제 더 이상 만나지 않을 것이라고 했다','傷心公園','https://image.tmdb.org/t/p/w1280/2OgrTUoGAGxpdh6xla1vfVToV04.jpg','https://image.tmdb.org/t/p/w1280/gdAbcShk0yBraK3LGaiLfjvTCCX.jpg','https://www.youtube.com/embed/2d1NRBSYbuo','https://image.tmdb.org/t/p/w1280/2OgrTUoGAGxpdh6xla1vfVToV04.jpg,https://image.tmdb.org/t/p/w1280/sqbazhh70nvj0CPp0EWSZnGOMOr.jpg,https://image.tmdb.org/t/p/w1280/rZ8wQUGNYhOv61I3pZxx1bfdqMm.jpg,https://image.tmdb.org/t/p/w1280/6QUe5Ky2jxk58jcoqlDTzMqQILv.jpg,https://image.tmdb.org/t/p/w1280/19dn0thOl8btRW4JsgZYfAxUT1h.jpg','2026-11-19','현재의 타이베이. 자신에게 무관심한 신에게 설명할 수 없는 애정을 품고 있는 타오는 사람을 시켜서 그를 폭행하고 고통을 뒤틀린 유대감으로 바꾸어 간다. 한편 이스탄불을 떠나 타이베이에 정착한 멜리는 술에 취한 핑에게 꽃 한 송이를 받고, 그 꽃을 통해 타오와 신의 이야기를 마주한다. 타오의 기억은 환상과 뒤섞여 흐려져 가고, 멜리는 자신의 이루지 못한 갈망을 돌아보며 홀로 간직한 기억을 놓아야 비로소 평화를 얻을 수 있는지 자문한다.','15세이상관람가','Wong Ka Ki','Elizabeth Tang,Melih Selçuk,Shin Cheung,王渝屏','다큐멘터리,로맨스',86,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1502759','주피터','Jupiter','https://image.tmdb.org/t/p/w1280/evfZVmo9kMu83qXTnu4HR8gTFSK.jpg','https://image.tmdb.org/t/p/w1280/8ct7Pvh7Pw4jd8yvmEV282evmQ7.jpg','','https://image.tmdb.org/t/p/w1280/evfZVmo9kMu83qXTnu4HR8gTFSK.jpg,https://image.tmdb.org/t/p/w1280/k19Er3Uy5q2ZXocJ0IXSbDvjdBA.jpg,https://image.tmdb.org/t/p/w1280/nqmCqQ4rygQAO82nmTXUcWPkMzB.jpg,https://image.tmdb.org/t/p/w1280/zAxC9EL60p7AeNnrHb6MCg2z1tC.jpg,https://image.tmdb.org/t/p/w1280/P7nC8RKtG3P6C2q5NxrLrgfGXc.jpg,https://image.tmdb.org/t/p/w1280/chaJbiQCeTEZZjk7yd3p5g8lNkl.jpg,https://image.tmdb.org/t/p/w1280/2KTanTdxHEgM03oWY73rr7h6Uap.jpg,https://image.tmdb.org/t/p/w1280/mpMFc5Er9fp0vO02UPmfxk3JITJ.jpg,https://image.tmdb.org/t/p/w1280/rQVqhkGLdHqrDJIKe7jYb8PjsQG.jpg,https://image.tmdb.org/t/p/w1280/iE7nUnIZSguWCuj5jzx29Sofv8E.jpg,https://image.tmdb.org/t/p/w1280/7kjjMD7M6mlTqIv5TGT5cl3DrtS.jpg,https://image.tmdb.org/t/p/w1280/x7tps9ijHcGhFytyhFmYPPGxHx4.jpg','2026-11-18','시카고에서 이민자 가족과 함께 남의 집을 청소하며 살아가는 주피터는 고된 일상 너머의 세계를 꿈꾼다. 어느 날 정체불명의 존재들이 그녀의 목숨을 노리고, 우주에서 온 전사 케인이 나타나 낯선 추격으로부터 그녀를 지킨다. 평범한 삶을 살던 주피터는 자신의 유전자가 거대한 우주 왕조의 상속권과 연결되어 있다는 믿기 어려운 이야기를 듣는다. 지구 밖에서는 행성마저 재산으로 거래되고, 막대한 부를 가진 아브라삭스 가문의 후계자들은 그녀의 존재를 두고 저마다 다른 계산을 한다. 화려한 궁전과 위험한 제안들 사이에서 주피터는 자신에게 주어진 권리가 지구의 모든 생명과 이어져 있음을 알아 간다. 어제까지 아무 결정권도 없던 그녀가, 이제 누구에게도 넘길 수 없는 선택을 내려야 한다.','전체관람가','Alexandre Smia','드니 메노셰,엘라 룸프,셀린 살레트,도미니크 블랑,Reda Kateb,André Dussollier,Frédéric Pierrot,세드릭 칸,Jérémy Lopez,Clotilde Courau,Pascal Greggory,Valeriu Andriuță,Max Geller,Giorgia Sinicorni,Nathan Willcocks,Anne Amandine,줄리엣 오브리,Егор Морозов','드라마,스릴러',87,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1518204','앨런','Allen','https://image.tmdb.org/t/p/w1280/51fGmBW7WjyJouP9TjIcxRpCUNk.jpg','https://image.tmdb.org/t/p/w1280/alhhrpj1PSAn5bfz4Os1k7Bweoj.jpg','https://www.youtube.com/embed/P8G5Y25W3eA','https://image.tmdb.org/t/p/w1280/51fGmBW7WjyJouP9TjIcxRpCUNk.jpg,https://image.tmdb.org/t/p/w1280/1hQEhz0uMKsEZXWUe7IB1qZoLRs.jpg,https://image.tmdb.org/t/p/w1280/lx28W2g0lWtOYSKWHV58ydj7G6V.jpg,https://image.tmdb.org/t/p/w1280/eowzuJXdoR7byFtvOj9krY90vgc.jpg,https://image.tmdb.org/t/p/w1280/zZxtUAwWTa9gvkIK79hkh1zl9WH.jpg,https://image.tmdb.org/t/p/w1280/kFh0OPHcW63CavdujF5OPgEcmMO.jpg,https://image.tmdb.org/t/p/w1280/mlR0s6HyXe5PJAJLn4uMXplmy18.jpg,https://image.tmdb.org/t/p/w1280/2d1i3VhVL73A0LP1aoi9raHOlOW.jpg,https://image.tmdb.org/t/p/w1280/veJjwBhTLD56yKsY1UaaQC7WU02.jpg,https://image.tmdb.org/t/p/w1280/goKoV1tU6Qs2M0HhjmaQUFtnVi1.jpg','2026-11-12','외계인과 만난 지 20년이 지났지만, 여전히 그 일을 잊지 못하는 피티. 마침내 옛 친구가 돌아왔다! 그런데 다시 나타난 이유가 예사롭지 않은 데다 뜻밖이기까지 하다.','15세이상관람가','Daley Pearson,Jeffrey Walker','T.J. Power,샬롯 닉다오,조쉬 헬먼,Emily Barclay,Benedict Hardie,엘리자 타마티,Edward A O\'Sullivan,Caitlin Niemotko,Tommy Broadmore,Kelly Butler,Mark Doggett,Christopher Sommers,Kaipo Heke,Chaydon Jay,Steven Bonutto,Connor Clarke,Perry Mooney,Daniel Tuiara,Josephine Flynn,Kaz Bowen,Scarlett Crabtree,Shakira Forstpointner,Danny Kim','SF,모험,코미디',107,NULL,1,'2026-11-17 11:44:06',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1527427','3mm의 사랑','3ミリの恋','https://image.tmdb.org/t/p/w1280/3zNOPB5i4vFWWblBbneLNCK7SxE.jpg','https://image.tmdb.org/t/p/w1280/cg0VwQsusxRMPNbyJUlUb1JBVH8.jpg','','https://image.tmdb.org/t/p/w1280/3zNOPB5i4vFWWblBbneLNCK7SxE.jpg,https://image.tmdb.org/t/p/w1280/ghcLKy6KoghkuBWTRk0lp0lxhqa.jpg,https://image.tmdb.org/t/p/w1280/yFtFUlBeq9lfO5bl36q8EGCOZvL.jpg,https://image.tmdb.org/t/p/w1280/6ac8pPK51qxSqnkQuxIYW8TGbCW.jpg,https://image.tmdb.org/t/p/w1280/xbDHgJwiO8RtudrkDvDQSWObze2.jpg,https://image.tmdb.org/t/p/w1280/tGvhhg9K4BB3xzNsuwuRIWJXO94.jpg,https://image.tmdb.org/t/p/w1280/rzcndQ0HejzYlMt10tiGZHSQ6p8.jpg,https://image.tmdb.org/t/p/w1280/6eOyT6zr0dEDtiNWMOhcg72PyzR.jpg,https://image.tmdb.org/t/p/w1280/ewDoiqkWGcRDarWkQBKraYKqaoj.jpg,https://image.tmdb.org/t/p/w1280/dlIIwNFAEWikfhVrKOP0WzaDaGs.jpg,https://image.tmdb.org/t/p/w1280/cnrlCY40WJxuebmKM9kSSGaACzb.jpg,https://image.tmdb.org/t/p/w1280/wzVpGwjzwLEdQfeU8PetLUUxnUn.jpg','2026-11-06','한국인 유학생을 사랑한 일본 소년이 가족을 위해 고향으로 돌아간 그를 다시 만나기 위해 여정을 떠나며 벌어지는 이야기','전체관람가','전진융','쿠로카와 소야,김지안,하야세 이코이,아라키 도와,소지 아라이,박지환,장혜진,최덕문,메구미,이치노세 와타루,오타니 료헤이','로맨스,드라마',105,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1543469','하트랜드','Heartland','https://image.tmdb.org/t/p/w1280/psTMZj8gvsfYVfvd7FZCHH4xL6P.jpg','https://image.tmdb.org/t/p/w1280/zhxlzxBlO1sWB1rPn7RmAoeQ2na.jpg','https://www.youtube.com/embed/ziIz59enN1c','https://image.tmdb.org/t/p/w1280/psTMZj8gvsfYVfvd7FZCHH4xL6P.jpg,https://image.tmdb.org/t/p/w1280/d1d6prv2fZFr44uqKUMLjQzKRjx.jpg,https://image.tmdb.org/t/p/w1280/AbMqeR5jA29wnHq96r2vFb8AcK8.jpg,https://image.tmdb.org/t/p/w1280/dyDrkxNU5YcJo1doCGbP7k2NDjR.jpg,https://image.tmdb.org/t/p/w1280/3lG13G4UBde8X1SHauOuAfwQnKE.jpg,https://image.tmdb.org/t/p/w1280/iSZ1MhNtUtmnUV4gOpjXS2rGDQq.jpg,https://image.tmdb.org/t/p/w1280/fKWov1J5p6lNEBLW3cw6HEOc7hE.jpg,https://image.tmdb.org/t/p/w1280/r84DiSIkez6GaLMSkgk7yTvGCn.jpg,https://image.tmdb.org/t/p/w1280/gVhJbOCns6GNsQaUbLszQUkFIKf.jpg,https://image.tmdb.org/t/p/w1280/b9NLiWn5HEJtJIcSZl1ebMT7iD.jpg,https://image.tmdb.org/t/p/w1280/xOENHnCLDPQkp0hLAYPeIp69v4Q.jpg,https://image.tmdb.org/t/p/w1280/oRO6uENYCWTyhYwoV94YEQpssKv.jpg','2026-11-13','한때 컨트리 음악계의 슈퍼스타였던 미스티 존스. 은둔 생활을 하던 그녀는 떠오르는 신예 컨트리 가수인 조카가 실종되자 사건 조사에 나서고, 그 과정에서 자신의 과거와 내슈빌의 어두운 이면을 마주한다. 사건을 파헤칠수록 수상쩍은 민낯을 드러내는 내슈빌. 그곳에선 모두, 심지어 미스티마저도, 겉으로 보이는 그대로가 아니다.','15세이상관람가','Shana Feste','제시카 차스테인,Carter Faith,Ross Lynch,존 호크스,개렛 헤들런드,Norbert Leo Butz,Hill Harper,Ben Dickey,폴 스파크스,제니퍼 네틀스,Tracy Lawrence,Matt Lowe,J.P. Edwards,윈 에버렛,Jayson Warner Smith,Sarah Helbringer,Skyler Day,Catherine Dyer,Holly Stevenson,Jordan Cox,Barry D Williams,Carol Swarbrick,Deborah Bowman,Kenneth Israel,Tim Plum,Nathan Hesse,Steven Rho,Kenneth Nance Jr.,Adelle Drahos,Aaron Goldenberg,Alexandra Ficken,Megan Henderson,Rowan Bousaid,Jordan Patrick,Brett A. Newton,Eric Jepson,Brenna Skalski,Dave Cutler,Channing Wilson,Isabelle Kusman,데이비드 리스달,Terrance Griffin,David Ferguson,Dax Dupuy,Paul Sopher,Rochester Brown Jr,Chantal Deegan,Jim Lauderdale,Tim Blanchard,Jason Suhrke,레이 캠벨','스릴러,미스터리',114,NULL,1,'2026-11-17 11:44:06',NULL);
