INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1560309','밤의 모든 연인들','すべて真夜中の恋人たち','https://image.tmdb.org/t/p/w1280/yGj2WiJSrPRvmnZ5GqVEaWmqJ4p.jpg','https://image.tmdb.org/t/p/w1280/hu59kewfoT7Brzimj8KOliuh5Ih.jpg','','https://image.tmdb.org/t/p/w1280/yGj2WiJSrPRvmnZ5GqVEaWmqJ4p.jpg,https://image.tmdb.org/t/p/w1280/thK0njduQqLpcMfaU8OvdhTZ7lc.jpg,https://image.tmdb.org/t/p/w1280/dvO0EwTwGgLM224o4NbT5zzxPou.jpg,https://image.tmdb.org/t/p/w1280/n3eUPF4FObiZlafmTDZRTEgQnnU.jpg,https://image.tmdb.org/t/p/w1280/cXuoR5NQC9rxmjV9QwmQQHhwgJ8.jpg,https://image.tmdb.org/t/p/w1280/jCRuXsoXrFJyTn6FAEbsBusW5bq.jpg,https://image.tmdb.org/t/p/w1280/vbcJQlPdlgDFErkhTvtioVl2EY7.jpg,https://image.tmdb.org/t/p/w1280/bbDSWq88ox909YOPge4lQZRHeRU.jpg,https://image.tmdb.org/t/p/w1280/czL2HnQu2hnXeb6TQFE0nqetL3f.jpg,https://image.tmdb.org/t/p/w1280/v5KEWBNSeVBI91hkonMOE7hSgxf.jpg,https://image.tmdb.org/t/p/w1280/8gI84OAfQAKUcy9hCuuqu21I7wC.jpg,https://image.tmdb.org/t/p/w1280/conopjkdNFuFYJ1cax1Wf5zuIdF.jpg','2026-11-13','도쿄에서 프리랜서 교정일을 하고 있는 30대 중반의 여성, 후유코. 곤경에 처했을 때 자신을 도와준 고등학교 물리 교사 미츠츠카와 조금씩 가까워지고 그와 \"빛\"에 대해 이야기를 나누기 시작하면서 조용했던 그의 삶이 술렁이기 시작한다.','전체관람가','소데 유키코','키시이 유키노,아사노 타다노부,모리타 미사토,후카가와 마이,시오노 아키히사,나카무라 유코,長井短,이노리 키라라,中井友望,하야시 유타','드라마,로맨스',139,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1562642','고스트 솔저','Ghost Soldier','https://image.tmdb.org/t/p/w1280/ggqvhSdAASrseKuMlzk51sbvbE8.jpg','https://image.tmdb.org/t/p/w1280/8Y4oJ5iUs3hgPcDB3SIEmsNYjZk.jpg','https://www.youtube.com/embed/UKaWzMf9Ybc','https://image.tmdb.org/t/p/w1280/ggqvhSdAASrseKuMlzk51sbvbE8.jpg,https://image.tmdb.org/t/p/w1280/nHhkgPp4kZUwlTTEZe5g3MoKl8g.jpg,https://image.tmdb.org/t/p/w1280/rhtE77mUo6I1LBGbtnVphRxcnQb.jpg,https://image.tmdb.org/t/p/w1280/oG2xaOERbYKs9RtEtOBkkDqqChb.jpg,https://image.tmdb.org/t/p/w1280/xN8v8UqG14qOFXSOgc0JrHsB1lN.jpg','2026-11-06','와이오밍의 한적한 고향 마을에서 헨리 피츠제럴드는 과거를 감춘 채 세상과 거리를 두고 조용히 살아간다. 그러나 한 자산관리 회사가 부패한 공권력과 외국 요원들을 끌어들여 이웃들의 드넓은 목장과 물줄기를 빼앗으려 들면서 마을의 평화는 무너지기 시작한다. 법도 정의도 힘없는 주민들의 편이 되어 주지 못하는 상황에서, 전직 그린베레이자 무기 체계 엔지니어였던 피츠는 오랫동안 봉인해 온 자신의 능력을 다시 꺼내 들기로 한다. 그는 이웃의 삶터를 지키겠다는 결심 하나로 은밀하게 움직이며, 상대가 누구인지조차 알지 못하는 사이 적들의 허를 찌른다. 거대한 자본과 폭력에 맞서는 한 남자의 외로운 전쟁, 그 불길은 점점 더 걷잡을 수 없이 번져 간다.','12세이상관람가','윌리엄 유뱅크','짐 커비즐,Cameron Gayden,올리비아 썰비,쉐어 위햄,Beau Knapp,마이클 아이언사이드,가렛 딜라헌트,Carlos Gómez,리키 휘틀,Alexej Manvelov,Jaina Lee Ortiz,스티븐 크리,Wil Johnson,Georgia Small,Mido Hamada,Ioan Paraschiv,Mark Hampton,Olivia Chenery,Jack McKenzie,Sorel Johnson,Ian Porter,Dylan Corbett-Bader,Tetiana Dar,Lina Sanden,Steve Chusak,제임스 보몬트,Gunner Wright,Tim Duthrane,George Vasile,Ionut Grama,Elizabeth Appleby,Ana Udroiu','액션,스릴러',90,NULL,1,'2026-11-17 11:44:06',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1595210','골칫덩어리 곰','Nuisance Bear','https://image.tmdb.org/t/p/w1280/hqDiQteXWMoyezEmbPy0nRYdUST.jpg','https://image.tmdb.org/t/p/w1280/An1QdmHWNxX2V03kq3akOCid69r.jpg','https://www.youtube.com/embed/dL4lFKY8Cy4','https://image.tmdb.org/t/p/w1280/hqDiQteXWMoyezEmbPy0nRYdUST.jpg,https://image.tmdb.org/t/p/w1280/pYRSQTTcU8oEIsX3oy4IZgCJcWy.jpg','2026-11-06','오랜 이동 경로를 따라온 북극곰은 관광객과 야생동물 관리관, 사냥꾼 들이 지배하는 인간의 세계를 헤쳐 나간다. 신성한 포식자가 골칫거리로 낙인찍히는 순간, 모두가 공유하는 이 풍경이 누구의 땅인지 불분명해진다.','전체관람가','Gabriela Osio Vanden,Jack Weisman','Mike Tunalaaq Gibbons,Saad Kassis-Mohamed','다큐멘터리',90,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1616187','즐거운 시간 보내세요','Enjoy Your Stay','https://image.tmdb.org/t/p/w1280/vBT0EuzccYXxisR3naZTR88fMZ1.jpg','https://image.tmdb.org/t/p/w1280/i6U43yPj31Ga38B7CvwymXK92OI.jpg','','https://image.tmdb.org/t/p/w1280/vBT0EuzccYXxisR3naZTR88fMZ1.jpg,https://image.tmdb.org/t/p/w1280/nY9jN6hIdTCqKcmVF8JXfYhCtEb.jpg,https://image.tmdb.org/t/p/w1280/9me4TMcUOuY19VnA0TyHY6SLKjT.jpg,https://image.tmdb.org/t/p/w1280/1FNIBfkoowY4JvTTSdy9d3GZ5v9.jpg','2026-11-18','필리핀 출신의 미등록 이주노동자 루즈는 눈 덮인 알프스 한가운데에서 수년간 고급 산장을 청소하며 눈에 띄지 않는 삶을 살아왔다. 그러나 고국에서 방영되는 리얼리티 TV 프로그램으로 인해 여섯 살 딸 소피아의 양육권을 잃게 될 위기에 처하자, 딸의 생일에는 반드시 돌아가겠다고 약속한다.','15세이상관람가','Dominik Locher','메르세데스 카브랄,Alexis Manenti,Anna Luna,Hasmine Killip,Irma Adlawan,Donna Cariaga,Madeleine Nicolas,Agathe Hauser,Georgia Rushton,Raphaël Tschudi,Kweku Sam,Thibault Liand,Erin Rose Espiritu,Ruby Ruiz,Yun Huang,Pierre-Antoine Dubey,Nico Antonio,Jun Nayra,Elora Españo,Sue Prado,Mary Ann Bernabe,Koso Morina,Helena Capco,Angeline Vitusha Rangan,Gérald Robert-Tissot,Clara Cantos,Lisa Kirby,Yanisse Mahmoudi,Gaetan Reine,Jean-Marie Pahud,Camilla Piccinini,Milanko Puranovic,Renaud Barkats,Ludovic Lumengo','드라마',100,NULL,1,'2026-11-17 11:44:07',NULL);
