INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1632188','메리 크리스마스, 엄마','Il fuoco che ti porti dentro','https://image.tmdb.org/t/p/w1280/ArRgIhvBRwHjVNYUh7acGpAaf1z.jpg','https://image.tmdb.org/t/p/w1280/kCfIZpqRsBe39Y1lUCxOAjgQ5VR.jpg','https://www.youtube.com/embed/5449efUJl90','https://image.tmdb.org/t/p/w1280/ArRgIhvBRwHjVNYUh7acGpAaf1z.jpg,https://image.tmdb.org/t/p/w1280/5Y0j7detCvtlTJeiLYH9eEefIfT.jpg','2026-11-19','밀라노에서 가족을 꾸리는 아들이 나폴리에서 온 괄괄한 어머니 때문에 골치를 앓는다. 그의 가족도 그러하고, 하는 행동을 보면 대다수 사람들이 불편해할 스타일이다. 그리고 크리스마스 전날의 악몽이 열린다.','15세이상관람가','Edoardo De Angelis','Vanessa Scalera,Lino Musella,Elena Radonicich,Ivana Lotito,Tommaso Ragno,Nicole Malaj,Samuele Mazza,Toni Laudadio,Giovanni Franzoni','드라마',93,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1664682','시간이 지울 수 없는 죄','Suzane von Richthofen: O Que o Tempo Não Apaga','https://image.tmdb.org/t/p/w1280/bjdgmMhTKcxqFO7RdXYhTlGzffB.jpg','https://image.tmdb.org/t/p/w1280/pO3BpFyC9B2fnfByJulxjs3hM4P.jpg','','https://image.tmdb.org/t/p/w1280/bjdgmMhTKcxqFO7RdXYhTlGzffB.jpg,https://image.tmdb.org/t/p/w1280/hl5AyXqpzs27TGVjIDN8IKJq2y5.jpg,https://image.tmdb.org/t/p/w1280/4gPxmumqXNcNXTLxbGqqPWR3aCC.jpg','2026-11-11','브라질을 뒤흔든 범죄가 발생한 지 수십 년이 지난 후, 수자니 폰 리히토펜이 단독 인터뷰에서 부모를 살해한 사건과 그 여파에 대해 이야기한다.','15세이상관람가','Lygia M. Barbosa,Paulo Gambale (Maká)','Suzane Von Richthofen,Roberto Tardelli,Cíntia Tucunduva,Solange Azevedo,Daniel Cravinhos,Claudia Bernasconi,Ilana Casoy,Valmir Salaro,Cristian Cravinhos,Jane Bellucci,Christian Dunker,Denivaldo Barni,Mário Sérgio de Oliveira,Eleonora Nacif,Mauro Nacif,Eliana de Freitas,Felipe Zecchini Muniz','범죄,다큐멘터리',100,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1666787','리처드 애버던','Avedon','https://image.tmdb.org/t/p/w1280/8mdZuwDtyhidCrb7ffsfl0FLeoN.jpg','https://image.tmdb.org/t/p/w1280/ziyEHM0P1TgvhVXIqqguoMAD0TJ.jpg','https://www.youtube.com/embed/q5ZYcXzV1L0','https://image.tmdb.org/t/p/w1280/8mdZuwDtyhidCrb7ffsfl0FLeoN.jpg,https://image.tmdb.org/t/p/w1280/7KskXIx3aNWUneGp82nW1jGRtg8.jpg,https://image.tmdb.org/t/p/w1280/wq1Gpt1ud5sodrkLq8ioek07aaZ.jpg,https://image.tmdb.org/t/p/w1280/9laPUoaHag0OAgfX0CggRcBzKAc.jpg,https://image.tmdb.org/t/p/w1280/1rL7G0XUR1sFZ7nz3rMoZpeo4PW.jpg','2026-11-06','지금까지 공개되지 않았던 사진과 자료 화면, 가까이에서 함께 작업한 이들의 인터뷰를 통해 리처드 애버던의 삶과 유산을 담아낸 다큐멘터리.','15세이상관람가','론 하워드','Richard Avedon','다큐멘터리',104,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1703273','불청객','L\'Autre','https://image.tmdb.org/t/p/w1280/SI0bfMSGMLXITcuANK15TlBTVz.jpg','https://image.tmdb.org/t/p/w1280/7zy3GMIvxSzB2sfSLuRhIhEcJ3T.jpg','https://www.youtube.com/embed/Uc-9vaMYoQ4','https://image.tmdb.org/t/p/w1280/SI0bfMSGMLXITcuANK15TlBTVz.jpg,https://image.tmdb.org/t/p/w1280/3AA6iAOD6zXudJYxmAXvvDvRElW.jpg,https://image.tmdb.org/t/p/w1280/fpRW2ofw5jM9O6pfDISVOhBdsZf.jpg,https://image.tmdb.org/t/p/w1280/htJWaZV1ASp2ZCRhAELr9KFjhM7.jpg,https://image.tmdb.org/t/p/w1280/rjd52oKim0TZgWeoNDZIVnyg7YX.jpg','2026-11-14','스탠은 다리에 인공관절을 넣는 수술을 받다가 도중에 깨어난 것 같은 트라우마에 휩싸여, 끊임없이 다리가 박살날 것 같은 공포에 사로잡힌다. 설상가상 병원에선 병실이 부족하다며 코마상태에 빠진 불상의 남자를 스탠의 병실에 집어넣는데, 그는 스탠과 단둘이 남겨지자 갑자기 말을 걸기 시작한다.','15세이상관람가','Alexandre Franchi','Pierre-Yves Cardinal,Bilel Chegrani,Maxime Genois,Karine Gonthier-Hyndman,Benoît Gouin,Marc Messier,Martyne Musau,Nahéma Ricci','스릴러,코미디',98,NULL,1,'2026-11-17 11:44:07',NULL);
