INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1794569','보호받지 못한 자: 머더 인 갈리시아','Desprotexida: el crimen de Pazos','https://image.tmdb.org/t/p/w1280/5DEE6tP6FOkgfjvoQYvjNjvt3cn.jpg','https://image.tmdb.org/t/p/w1280/uvwAKeTTf9s0k69xelRXQbs6Hb7.jpg','https://www.youtube.com/embed/V7qdKH-USL8','https://image.tmdb.org/t/p/w1280/5DEE6tP6FOkgfjvoQYvjNjvt3cn.jpg,https://image.tmdb.org/t/p/w1280/dqTVEBGeqprfBwXBPUdXjCpr1JJ.jpg','2026-11-06','2015년, 도둑으로 추정되는 이들이 이사벨 푸엔테스를 자택에서 죽음 직전까지 몰고 갔다. 이 다큐멘터리는 사건 직후 그녀와 가까운 사람들에게로 의심이 옮겨가게 된 과정을 추적한다.','12세이상관람가','Jorge Laplace','Eduardo Pérez \"Perreras\",Maribel Tarrazo,Corona Salgado,Eduardo Pérez,Javier González,Fernando Serulla','다큐멘터리,범죄',65,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1809258','광안 : 세자의 여자','광안 : 세자의 여자','','https://image.tmdb.org/t/p/w1280/g1aa08wocACsY5c9GYQZhojwekR.jpg','','','2026-11-18','미친 눈을 가진 자라 하여 ‘광안’이라 불리는 세자 ‘이현’을 암살하기 위해 궁녀로 위장해 서궁에 잠입한 자객 ‘은우’가 계획과 달리 그를 사랑하게 되면서, 정해진 운명을 거스르기 시작하는 이야기','15세이상관람가','조바른','성준,츄,스윙스,김응수,조수향,최홍일,염승이','로맨스,드라마',93,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('1823907','러셀 브랜드: 모른 척했던 비밀','Russell Brand: Open Secret','https://image.tmdb.org/t/p/w1280/sdYU5S9SMWk9Wr3IMP0538k341l.jpg','https://image.tmdb.org/t/p/w1280/rYhOUFkNRwD4ETV7BFcsID53yyi.jpg','https://www.youtube.com/embed/wiXS3J3LeOA','https://image.tmdb.org/t/p/w1280/sdYU5S9SMWk9Wr3IMP0538k341l.jpg','2026-11-13','코미디 스타로 혜성처럼 떠오른 러셀 브랜드가 성범죄 의혹에 휩싸여 형사재판에 서기까지, 그의 급격한 성공과 추락을 조명하는 다큐멘터리.','15세이상관람가','Olivia Issacs','러셀 브랜드,George Monbiot,Nish Kumar,Amanda Alguero Alejos,Mark Pinheiro,Harriet Kemsley,Rosamund Urwin,Charlotte Wace,Jordan Martin,케이티 페리,Laura Gallacher,Jemima Marcelle Goldsmith O\'Reilly,Georgina Baillie,Andrew Sachs,조나단 로스,David Walliams,엘리자베스 2세,Alex E. Jones,터커 칼슨','다큐멘터리,범죄',84,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('656908','라마야나','रामायणम्','https://image.tmdb.org/t/p/w1280/yHVZncPRZr63mezRX20IyKLrSkv.jpg','https://image.tmdb.org/t/p/w1280/gOWnXaBxqT6k2y40hKfYU6c0Ym.jpg','https://www.youtube.com/embed/LW3LVsS7JAM','https://image.tmdb.org/t/p/w1280/yHVZncPRZr63mezRX20IyKLrSkv.jpg,https://image.tmdb.org/t/p/w1280/ysoJexwslfJnSXcHNNF1A9EtDbB.jpg,https://image.tmdb.org/t/p/w1280/prbMZ3DPf8taS6JYQd6igPnm2mA.jpg,https://image.tmdb.org/t/p/w1280/ks72NqTPhpupk207NXiqmZIQQVI.jpg,https://image.tmdb.org/t/p/w1280/wE38Vvr1w577h1ndljzaEnXTKQ3.jpg,https://image.tmdb.org/t/p/w1280/kJAklyTOaIu3BTxYGtlw3m1HlHo.jpg,https://image.tmdb.org/t/p/w1280/wfGbMf0e9tZhq7ZQ1uKgtWQCKOl.jpg,https://image.tmdb.org/t/p/w1280/xmtdDK5FaBgwDPc9oUSRDmBFJfm.jpg,https://image.tmdb.org/t/p/w1280/f5Lq2ndFETM1V5RNmFhpl2FKrHL.jpg,https://image.tmdb.org/t/p/w1280/zCYGEG326MprR1jBxOW2FPiv2dP.jpg,https://image.tmdb.org/t/p/w1280/y8tFY6Rbj1Eev0hPEBCTLZhSSvF.jpg,https://image.tmdb.org/t/p/w1280/oy1XAE5d6GtQui2uSkiCryyjRLQ.jpg','2026-11-05','고대 왕국 아요디아의 왕자 라마는 형제들과 함께 자라며 왕위를 이을 자로서 덕과 무예를 갈고닦는다. 수많은 시험을 이겨내고 미틸라의 공주 시타와 혼인한 그는 백성의 축복 속에 왕위 계승을 눈앞에 두지만, 아버지 다샤라타 왕이 오래전에 맺은 약속 하나가 모든 것을 뒤바꾼다. 라마는 아버지의 맹세를 지키기 위해 왕좌를 내려놓고 14년의 유배길에 오르고, 시타와 아우 락슈마나는 기꺼이 그 뒤를 따른다. 한편 바다 건너 황금의 섬 랑카에서는 불멸의 힘을 손에 넣은 마왕 라바나가 복수의 칼날을 갈고 있다. 숲속의 고요한 나날이 이어지던 어느 날, 아득한 옛날부터 라마와 라바나의 운명을 하나로 묶어 온 예언이 마침내 움직이기 시작하는데...','12세이상관람가','Nitesh Tiwari','란비르 카푸르,Yash,Sai Pallavi,Ravi Dubey,अरुण गोविल,लारा दत्ता,Rakul Preet Singh,इंदिरा कृष्णन,Sonal Jha,Adinath Kothare,కాజల్ అగర్వాల్,Nitish Sharma,अनुपम खेर,Vivek Oberoi,Harish Uthaman,Kunal Kapoor,शीबा चड्ढा,Shishir Sharma,Ajinkya Deo,Mukesh Tiwari,Sonia Balani,Surabhi Das,Riya Kapoor,Shobana,Raghav Juyal,Faisal Malik,Parminder Chadha,Saurabh Sachdeva,सनी द्योल,Kanchan Chetal,Chetan Hansraj,Dhaniksh Dadhich,Kiara Sadh,Raghav Malhotra,Dishita Sehgal,Pravin Manjarekar','판타지,액션,모험',195,NULL,1,'2026-11-17 11:44:06',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('747509','풍선껌 소녀','泡泡糖女孩','https://image.tmdb.org/t/p/w1280/ja5SWrhlMWR1mhgECPZxnvnDT8i.jpg','https://image.tmdb.org/t/p/w1280/9WKeQ2rOHxVbl93DvmL8DpycF2d.jpg','https://www.youtube.com/embed/o-LkpJ4ACxk','https://image.tmdb.org/t/p/w1280/ja5SWrhlMWR1mhgECPZxnvnDT8i.jpg,https://image.tmdb.org/t/p/w1280/sLTSNirdD8FQxyC86NWpSiHShak.jpg','2026-11-19','1994년 싱가포르, 이제 막 초등학교에 입학한 일곱 살 소녀 \'아걸\'은 조금 특별한 환경에서 자라고 있다. 부모의 별거로 인해 낡고 작은 아파트에서 말괄량이 다섯 살 여동생 \'아티엔\', 야간 근무를 하는 과묵한 아빠, 그리고 까칠한 할머니와 함께 살아가고 있다. 주말마다 만나는 엄마는 장난감과 맛있는 음식으로 아이들의 환심을 사려 하지만, 늘 사랑을 갈구하며 어딘가 신뢰하기 힘들다.','15세이상관람가','Ang Geck Geck','Xuan Jing Ong,Sydney Wong,Carrie Wong,James Seah,Doreen Toh,Benjamin Heng,Vivianne Li,Joey Sin,Jasmin Kamal,Tan Yong Jia,Johnson Lim Kah Hong,Leong E-Xuan,Alan Tan,Evon Teh,Alena Teh,Minsley Chin,Maria Wahab','드라마',99,NULL,1,'2026-11-17 11:44:07',NULL);
INSERT INTO `movietb` (`movieno`, `movienm`, `movieen`, `moviebackimg`, `moviepostimg`, `movieyoutube`, `steelcut`, `releaseday`, `intro`, `ratingno`, `directornm`, `actor`, `genre`, `times`, `endday`, `moviestatus`, `adate`, `mdate`) VALUES ('951018','폭스 언더 핑크문','روباه و ماه صورتی','https://image.tmdb.org/t/p/w1280/sdMLtTxADRF3WAHmtL9oUFNY5wt.jpg','https://image.tmdb.org/t/p/w1280/67hNnsOQmC6DDYf7SuZc3ReldsB.jpg','https://www.youtube.com/embed/HBlaV0xOBLI','https://image.tmdb.org/t/p/w1280/sdMLtTxADRF3WAHmtL9oUFNY5wt.jpg,https://image.tmdb.org/t/p/w1280/zgJKvH13rrCmTi6tcnFzkRyAXDh.jpg','2026-11-13','이란에 사는 자유로운 영혼의 16세 아프가니스탄 출신 예술가 소라야의 섬세한 질감의 자화상. 5년째 유럽으로 향하는 길을 찾아온 그녀는 휴대전화로 모든 것을 서늘할 만큼 생생히 기록하는 한편, 자신의 두려움과 걱정을 경이로운 예술 작품에 모두 쏟아낸다.','12세이상관람가','Mehrdad Oskouei','Soraya Akhlaghi','다큐멘터리',77,NULL,1,'2026-11-17 11:44:07',NULL);
